INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-09', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 9', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 9);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 1, 'attach', 'gắn; đính kèm', 'verb', '[{"en":"Please attach a recent photo to your application form.","vi":"Vui lòng đính kèm một ảnh gần đây vào đơn đăng ký."},{"en":"I forgot to attach the file to my email.","vi":"Tôi quên đính kèm tệp vào email."},{"en":"The shelf is attached to the wall with four screws.","vi":"Cái kệ được gắn vào tường bằng bốn con vít."}]', '[{"phrase":"attach a file"},{"phrase":"attach a photo"},{"phrase":"attach importance to"}]', 'attach sth to sth', '/əˈtætʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attac/attach__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 2, 'hell', 'địa ngục; cực hình', 'noun', '[{"en":"Driving in rush hour traffic is pure hell.","vi":"Lái xe vào giờ cao điểm đúng là cực hình."},{"en":"She went through hell when her company closed down.","vi":"Cô ấy đã trải qua một thời gian cực khổ khi công ty đóng cửa."},{"en":"We had a hell of a time finding a parking space.","vi":"Chúng tôi đã rất vất vả mới tìm được chỗ đậu xe."}]', '[{"phrase":"pure hell"},{"phrase":"go through hell"},{"phrase":"a hell of a"}]', 'Khẩu ngữ, chỉ dùng trong tình huống thân mật', '/hel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hel/hell_/hell__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 3, 'everywhere', 'khắp nơi; ở mọi nơi', 'adverb', '[{"en":"I''ve looked everywhere, but I can''t find my keys.","vi":"Tôi đã tìm khắp nơi mà không thấy chìa khóa đâu."},{"en":"There were people everywhere at the night market.","vi":"Ở chợ đêm, đâu đâu cũng có người."},{"en":"You can buy this kind of phone charger almost everywhere.","vi":"Bạn có thể mua loại sạc điện thoại này ở hầu như mọi nơi."}]', '[{"phrase":"look everywhere"},{"phrase":"almost everywhere"},{"phrase":"everywhere else"}]', NULL, '/ˈevriwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everywhere__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 4, 'advise', 'khuyên; tư vấn', 'verb', '[{"en":"The doctor advised me to get more sleep.","vi":"Bác sĩ khuyên tôi nên ngủ nhiều hơn."},{"en":"I would advise you not to drive in this weather.","vi":"Tôi khuyên bạn không nên lái xe trong thời tiết thế này."},{"en":"Our teacher advises students on which courses to take.","vi":"Thầy giáo tư vấn cho sinh viên nên chọn học những môn nào."}]', '[{"phrase":"advise sb to do sth"},{"phrase":"strongly advise"},{"phrase":"advise on"}]', 'advise (v) ≠ advice (n)', '/ədˈvaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advis/advise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 5, 'household', 'hộ gia đình; gia đình', 'noun', '[{"en":"Almost every household in the village has a motorbike.","vi":"Hầu như hộ gia đình nào trong làng cũng có xe máy."},{"en":"Who does the cooking in your household?","vi":"Trong gia đình bạn, ai là người nấu ăn?"},{"en":"The average household income in the city has risen this year.","vi":"Thu nhập trung bình của các hộ gia đình trong thành phố đã tăng trong năm nay."}]', '[{"phrase":"household income"},{"phrase":"household chores"},{"phrase":"head of the household"}]', NULL, '/ˈhaʊshəʊld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hou/house/household__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 6, 'acknowledge', 'thừa nhận; xác nhận', 'verb', '[{"en":"He finally acknowledged that he had made a mistake.","vi":"Cuối cùng anh ấy cũng thừa nhận mình đã mắc lỗi."},{"en":"The company acknowledged the problem and apologized to its customers.","vi":"Công ty đã thừa nhận vấn đề và xin lỗi khách hàng."},{"en":"Please acknowledge receipt of this email as soon as possible.","vi":"Vui lòng xác nhận đã nhận được email này càng sớm càng tốt."}]', '[{"phrase":"acknowledge receipt of"},{"phrase":"acknowledge the problem"},{"phrase":"publicly acknowledge"}]', NULL, '/əkˈnɑːlɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ack/ackno/acknowledge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 7, 'reward', 'phần thưởng; tiền thưởng', 'noun', '[{"en":"The children got ice cream as a reward for being good.","vi":"Bọn trẻ được ăn kem như một phần thưởng vì đã ngoan."},{"en":"The owner is offering a reward for finding her lost dog.","vi":"Cô chủ đang treo thưởng cho ai tìm thấy chú chó bị lạc của mình."},{"en":"Seeing my students succeed is the greatest reward of teaching.","vi":"Thấy học trò thành công là phần thưởng lớn nhất của nghề dạy học."}]', '[{"phrase":"as a reward"},{"phrase":"offer a reward"},{"phrase":"reward for"}]', 'Cũng là động từ: reward sb for sth (thưởng)', '/rɪˈwɔːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rew/rewar/reward__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 8, 'east', 'phía đông; hướng đông', 'noun', '[{"en":"The sun rises in the east and sets in the west.","vi":"Mặt trời mọc ở phía đông và lặn ở phía tây."},{"en":"Their farm is about ten kilometers to the east of town.","vi":"Trang trại của họ cách thị trấn khoảng mười cây số về phía đông."},{"en":"A cold wind is blowing from the east today.","vi":"Hôm nay có gió lạnh thổi từ hướng đông."}]', '[{"phrase":"in the east"},{"phrase":"to the east of"},{"phrase":"from the east"}]', NULL, '/iːst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/east_/east__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 9, 'hat', 'mũ; nón', 'noun', '[{"en":"Don''t forget to wear a hat in the sun.","vi":"Đừng quên đội mũ khi ra nắng."},{"en":"He took off his hat when he walked into the room.","vi":"Anh ấy bỏ mũ ra khi bước vào phòng."},{"en":"My grandmother bought me a warm wool hat for winter.","vi":"Bà mua cho tôi một chiếc mũ len ấm để đội vào mùa đông."}]', '[{"phrase":"wear a hat"},{"phrase":"take off your hat"},{"phrase":"wool hat"},{"phrase":"straw hat"}]', NULL, '/hæt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hat/hat__/hat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 10, 'academic', '(thuộc) học thuật; (thuộc) học tập', 'adjective', '[{"en":"She has always had excellent academic results.","vi":"Cô ấy luôn có kết quả học tập xuất sắc."},{"en":"The new academic year starts in early September.","vi":"Năm học mới bắt đầu vào đầu tháng Chín."},{"en":"Writing an academic paper takes a lot of time and research.","vi":"Viết một bài báo học thuật cần nhiều thời gian và nghiên cứu."}]', '[{"phrase":"academic year"},{"phrase":"academic performance"},{"phrase":"academic writing"}]', NULL, '/ˌækəˈdemɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aca/acade/academic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 11, 'voter', 'cử tri; người bỏ phiếu', 'noun', '[{"en":"Every voter must show an ID card at the polling station.","vi":"Mỗi cử tri phải xuất trình thẻ căn cước tại điểm bỏ phiếu."},{"en":"More young voters took part in the election this year.","vi":"Năm nay có nhiều cử tri trẻ tham gia bầu cử hơn."},{"en":"The team captain was chosen by a small group of voters.","vi":"Đội trưởng được một nhóm nhỏ người bỏ phiếu lựa chọn."}]', '[{"phrase":"young voters"},{"phrase":"first-time voters"},{"phrase":"voter turnout"}]', NULL, '/ˈvəʊtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vot/voter/voter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 12, 'meanwhile', 'trong khi đó; trong lúc chờ đợi', 'adverb', '[{"en":"Dinner will be ready soon; meanwhile, you can set the table.","vi":"Bữa tối sắp xong rồi; trong lúc chờ, bạn dọn bàn ăn nhé."},{"en":"I cooked dinner, and meanwhile my husband gave the kids a bath.","vi":"Tôi nấu bữa tối, còn trong khi đó chồng tôi tắm cho bọn trẻ."},{"en":"Prices keep rising; meanwhile, wages have stayed the same.","vi":"Giá cả liên tục tăng; trong khi đó, lương vẫn giữ nguyên."}]', '[{"phrase":"in the meanwhile"},{"phrase":"and meanwhile"}]', NULL, '/ˈmiːnwaɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/meanw/meanwhile__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 13, 'furthermore', 'hơn nữa; ngoài ra', 'adverb', '[{"en":"The hotel is cheap; furthermore, it is close to the beach.","vi":"Khách sạn này rẻ; hơn nữa, nó lại gần biển."},{"en":"Furthermore, the new system will save staff a lot of time.","vi":"Hơn nữa, hệ thống mới sẽ giúp nhân viên tiết kiệm nhiều thời gian."},{"en":"The course is free, and furthermore, you get a certificate at the end.","vi":"Khóa học miễn phí, và ngoài ra bạn còn được nhận chứng chỉ khi kết thúc."}]', '[{"phrase":"and furthermore"},{"phrase":"furthermore, it is"}]', 'Trang trọng, thường dùng trong văn viết', '/ˌfɜːrðərˈmɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fur/furth/furthermore__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 14, 'accuse', 'buộc tội; cáo buộc', 'verb', '[{"en":"She accused me of reading her diary.","vi":"Cô ấy buộc tội tôi đã đọc nhật ký của cô ấy."},{"en":"Are you accusing me of lying to you about the money?","vi":"Bạn đang buộc tội tôi nói dối bạn về chuyện tiền bạc à?"},{"en":"The company was accused of paying its workers too little.","vi":"Công ty bị cáo buộc trả lương quá thấp cho công nhân."}]', '[{"phrase":"accuse sb of"},{"phrase":"be accused of"},{"phrase":"falsely accuse"}]', 'accuse sb of (doing) sth', '/əˈkjuːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accus/accuse__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 15, 'scientific', '(thuộc) khoa học; có tính khoa học', 'adjective', '[{"en":"There is no scientific evidence that this tea helps you lose weight.","vi":"Không có bằng chứng khoa học nào cho thấy loại trà này giúp giảm cân."},{"en":"Scientific research often takes many years and a lot of money.","vi":"Nghiên cứu khoa học thường mất nhiều năm và tốn nhiều tiền."},{"en":"We need a more scientific approach to solving this problem.","vi":"Chúng ta cần một cách tiếp cận khoa học hơn để giải quyết vấn đề này."}]', '[{"phrase":"scientific evidence"},{"phrase":"scientific research"},{"phrase":"scientific approach"}]', NULL, '/ˌsaɪənˈtɪfɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sci/scien/scientific__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 16, 'wage', 'tiền lương; tiền công', 'noun', '[{"en":"The minimum wage will go up again next year.","vi":"Mức lương tối thiểu sẽ lại tăng vào năm sau."},{"en":"Workers at the factory are asking for higher wages.","vi":"Công nhân ở nhà máy đang đòi được trả lương cao hơn."},{"en":"He earns a good wage working in a hotel kitchen.","vi":"Anh ấy kiếm được mức lương khá khi làm trong bếp của một khách sạn."}]', '[{"phrase":"minimum wage"},{"phrase":"higher wages"},{"phrase":"earn a wage"}]', 'wage: lương theo giờ/tuần ≠ salary: lương tháng/năm', '/weɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wag/wage_/wage__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 17, 'absence', 'sự vắng mặt; sự thiếu', 'noun', '[{"en":"Nobody noticed his absence from the meeting.","vi":"Không ai để ý anh ấy vắng mặt trong cuộc họp."},{"en":"My neighbor fed my cat during my absence.","vi":"Hàng xóm cho mèo của tôi ăn trong thời gian tôi vắng nhà."},{"en":"The absence of clear rules caused a lot of confusion.","vi":"Việc thiếu quy định rõ ràng đã gây ra nhiều nhầm lẫn."}]', '[{"phrase":"absence from"},{"phrase":"in the absence of"},{"phrase":"long absence"}]', NULL, '/ˈæbsəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/absen/absence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 18, 'construct', 'xây dựng; tạo dựng; đặt (câu)', 'verb', '[{"en":"The bridge was constructed more than a hundred years ago.","vi":"Cây cầu được xây dựng cách đây hơn một trăm năm."},{"en":"The city plans to construct a new hospital near the river.","vi":"Thành phố dự định xây một bệnh viện mới gần sông."},{"en":"Can you construct a sentence using this new word?","vi":"Bạn có thể đặt một câu với từ mới này không?"}]', '[{"phrase":"construct a building"},{"phrase":"construct a bridge"},{"phrase":"construct a sentence"}]', NULL, '/kənˈstrʌkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstruct__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 19, 'remark', 'lời nhận xét; lời bình luận', 'noun', '[{"en":"His rude remark about her cooking really upset her.","vi":"Lời nhận xét khiếm nhã của anh ấy về tài nấu ăn của cô ấy khiến cô rất buồn."},{"en":"She made a few remarks about the weather and then left.","vi":"Cô ấy bình luận vài câu về thời tiết rồi rời đi."},{"en":"Don''t take his remark seriously; he was only joking.","vi":"Đừng để bụng lời nhận xét của anh ấy; anh ấy chỉ đùa thôi."}]', '[{"phrase":"make a remark"},{"phrase":"rude remark"},{"phrase":"passing remark"}]', 'Cũng là động từ: remark on sth (nhận xét về)', '/rɪˈmɑːrk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remar/remark__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 20, 'medicine', 'thuốc; y học', 'noun', '[{"en":"Take this medicine three times a day after meals.","vi":"Uống thuốc này ba lần một ngày sau bữa ăn."},{"en":"Keep all medicine out of the reach of small children.","vi":"Hãy để tất cả thuốc xa tầm tay trẻ nhỏ."},{"en":"My sister is studying medicine at university.","vi":"Chị tôi đang học ngành y ở đại học."}]', '[{"phrase":"take medicine"},{"phrase":"study medicine"},{"phrase":"modern medicine"}]', 'take medicine = uống thuốc', '/ˈmedɪsn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/medic/medicine__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 21, 'professor', 'giáo sư; giảng viên đại học', 'noun', '[{"en":"My professor gave me some useful advice about my thesis.","vi":"Giáo sư của tôi đã cho tôi vài lời khuyên hữu ích về luận văn."},{"en":"She became a professor of chemistry at the age of forty.","vi":"Bà ấy trở thành giáo sư hóa học ở tuổi bốn mươi."},{"en":"Our history professor always tells funny stories in class.","vi":"Giảng viên môn lịch sử của chúng tôi luôn kể chuyện vui trong giờ học."}]', '[{"phrase":"professor of"},{"phrase":"university professor"},{"phrase":"history professor"}]', 'Ở Mỹ, professor thường dùng chung cho giảng viên đại học', '/prəˈfesər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profe/professor__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 22, 'rare', 'hiếm; hiếm có; (thịt) tái', 'adjective', '[{"en":"This plant is very rare and only grows in the mountains.","vi":"Loài cây này rất hiếm và chỉ mọc trên núi."},{"en":"It is rare for him to be late for work.","vi":"Hiếm khi anh ấy đi làm muộn."},{"en":"Could I have my steak rare, please?","vi":"Cho tôi món bít tết tái nhé."}]', '[{"phrase":"extremely rare"},{"phrase":"rare species"},{"phrase":"it is rare for"}]', NULL, '/rer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rar/rare_/rare__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 23, 'intention', 'ý định; dự định', 'noun', '[{"en":"I have no intention of leaving my job right now.","vi":"Tôi không có ý định nghỉ việc lúc này."},{"en":"Her intention was to help, not to cause trouble.","vi":"Ý định của cô ấy là giúp đỡ, chứ không phải gây rắc rối."},{"en":"He announced his intention to study abroad next year.","vi":"Anh ấy thông báo dự định đi du học vào năm sau."}]', '[{"phrase":"have no intention of"},{"phrase":"announce your intention"},{"phrase":"good intentions"}]', 'intention of doing / intention to do', '/ɪnˈtenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intention__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 24, 'dozen', 'tá (mười hai); hàng chục', 'noun', '[{"en":"I bought a dozen eggs at the market this morning.","vi":"Sáng nay tôi mua một tá trứng ở chợ."},{"en":"There were dozens of people waiting outside the shop.","vi":"Có hàng chục người đang đợi bên ngoài cửa hàng."},{"en":"I''ve told you a dozen times to close the door.","vi":"Tôi đã bảo bạn cả chục lần là phải đóng cửa rồi."}]', '[{"phrase":"a dozen eggs"},{"phrase":"dozens of"},{"phrase":"half a dozen"}]', 'a dozen eggs (không có ''of'') · dozens of people', '/ˈdʌzn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doz/dozen/dozen__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 25, 'settlement', 'sự thỏa thuận; sự dàn xếp; khu định cư', 'noun', '[{"en":"The two companies finally reached a settlement after months of talks.","vi":"Hai công ty cuối cùng đã đạt được thỏa thuận sau nhiều tháng đàm phán."},{"en":"People built a small settlement beside the river long ago.","vi":"Từ rất lâu, người ta đã lập một khu định cư nhỏ bên sông."},{"en":"The fishing settlement slowly grew into a busy port town.","vi":"Khu định cư của dân chài dần phát triển thành một thị trấn cảng nhộn nhịp."}]', '[{"phrase":"reach a settlement"},{"phrase":"out-of-court settlement"},{"phrase":"small settlement"}]', NULL, '/ˈsetlmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/set/settl/settlement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 26, 'gap', 'khe hở; khoảng trống; khoảng cách', 'noun', '[{"en":"The cat got out through a gap in the fence.","vi":"Con mèo chui ra ngoài qua một khe hở ở hàng rào."},{"en":"There is a big age gap between me and my brother.","vi":"Giữa tôi và anh trai có khoảng cách tuổi tác lớn."},{"en":"The gap between rich and poor is getting wider.","vi":"Khoảng cách giàu nghèo đang ngày càng lớn."}]', '[{"phrase":"a gap in"},{"phrase":"age gap"},{"phrase":"gap between"},{"phrase":"fill the gap"}]', NULL, '/ɡæp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gap/gap__/gap__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 27, 'widely', 'rộng rãi; nhiều', 'adverb', '[{"en":"English is widely spoken in this part of the city.","vi":"Tiếng Anh được sử dụng rộng rãi ở khu vực này của thành phố."},{"en":"This book is widely read by high school students.","vi":"Cuốn sách này được rất nhiều học sinh cấp ba đọc."},{"en":"Prices vary widely from one shop to another.","vi":"Giá cả chênh lệch nhiều giữa các cửa hàng."}]', '[{"phrase":"widely used"},{"phrase":"widely available"},{"phrase":"vary widely"}]', NULL, '/ˈwaɪdli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wid/widel/widely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 28, 'minimum', 'mức tối thiểu', 'noun', '[{"en":"You need a minimum of three people to play this game.","vi":"Cần tối thiểu ba người để chơi trò này."},{"en":"Please keep the noise to a minimum; the baby is sleeping.","vi":"Hãy giữ tiếng ồn ở mức tối thiểu nhé; em bé đang ngủ."},{"en":"The course takes a minimum of two years to finish.","vi":"Khóa học cần tối thiểu hai năm để hoàn thành."}]', '[{"phrase":"a minimum of"},{"phrase":"keep to a minimum"},{"phrase":"bare minimum"}]', 'minimum ≠ maximum (mức tối đa)', '/ˈmɪnɪməm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minim/minimum__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 29, 'northern', '(thuộc) phía bắc; miền Bắc', 'adjective', '[{"en":"They live in a small town in northern Vietnam.","vi":"Họ sống ở một thị trấn nhỏ ở miền Bắc Việt Nam."},{"en":"Winters in the northern part of the country are very cold.","vi":"Mùa đông ở phía bắc đất nước rất lạnh."},{"en":"We stayed at a hotel on the northern edge of the lake.","vi":"Chúng tôi ở một khách sạn nằm ở rìa phía bắc của hồ."}]', '[{"phrase":"northern part"},{"phrase":"northern edge"},{"phrase":"northern border"}]', NULL, '/ˈnɔːrðərn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/north/northern__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-09', 30, 'estate', 'bất động sản; điền trang; tài sản', 'noun', '[{"en":"My uncle works in real estate in the city center.","vi":"Chú tôi làm trong ngành bất động sản ở trung tâm thành phố."},{"en":"The family owns a large tea estate in the hills.","vi":"Gia đình ấy sở hữu một đồn điền chè lớn trên đồi."},{"en":"Her grandfather left his whole estate to the local school.","vi":"Ông của cô ấy để lại toàn bộ tài sản cho trường học địa phương."}]', '[{"phrase":"real estate"},{"phrase":"real estate agent"},{"phrase":"country estate"}]', 'real estate (Mỹ) = property (Anh): bất động sản', '/ɪˈsteɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estat/estate__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-10', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 10', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 10);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 1, 'equally', 'như nhau; đều; bằng nhau', 'adverb', '[{"en":"Please divide the cake equally between the four children.","vi":"Hãy chia đều chiếc bánh cho bốn đứa trẻ."},{"en":"Both teams played equally well in the second half.","vi":"Cả hai đội đều chơi hay như nhau trong hiệp hai."},{"en":"Sleep is equally important for adults and children.","vi":"Giấc ngủ quan trọng như nhau đối với người lớn và trẻ em."}]', '[{"phrase":"equally important"},{"phrase":"equally well"},{"phrase":"divide equally"},{"phrase":"share equally"}]', NULL, '/ˈiːkwəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equal/equally__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 2, 'expose', 'phơi ra; để lộ; vạch trần', 'verb', '[{"en":"Babies shouldn''t be exposed to the sun for too long.","vi":"Không nên để trẻ sơ sinh phơi nắng quá lâu."},{"en":"Removing the old paint exposed the beautiful wood underneath.","vi":"Việc cạo lớp sơn cũ đã để lộ phần gỗ đẹp bên dưới."},{"en":"A young reporter exposed the company''s secret plan.","vi":"Một phóng viên trẻ đã vạch trần kế hoạch bí mật của công ty."}]', '[{"phrase":"be exposed to"},{"phrase":"expose the truth"},{"phrase":"expose a secret"}]', NULL, '/ɪkˈspəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expos/expose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 3, 'alive', 'còn sống; sôi động', 'adjective', '[{"en":"My grandmother is still alive and very healthy at ninety.","vi":"Bà tôi vẫn còn sống và rất khỏe mạnh ở tuổi chín mươi."},{"en":"We need to water these plants to keep them alive.","vi":"Chúng ta cần tưới những cái cây này để giữ cho chúng sống."},{"en":"The city really comes alive at night.","vi":"Thành phố thực sự trở nên sôi động vào ban đêm."}]', '[{"phrase":"still alive"},{"phrase":"stay alive"},{"phrase":"keep alive"},{"phrase":"come alive"}]', 'không đứng trước danh từ (dùng living: a living animal)', '/əˈlaɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ali/alive/alive__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 4, 'shut', 'đóng; nhắm lại; đóng cửa', 'verb', '[{"en":"Please shut the door when you leave.","vi":"Làm ơn đóng cửa lại khi bạn ra ngoài."},{"en":"She shut her eyes and tried to sleep.","vi":"Cô ấy nhắm mắt lại và cố ngủ."},{"en":"Many small shops shut early on Sundays.","vi":"Nhiều cửa hàng nhỏ đóng cửa sớm vào Chủ nhật."}]', '[{"phrase":"shut the door"},{"phrase":"shut your eyes"},{"phrase":"shut down"}]', 'shut – shut – shut', '/ʃʌt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shu/shut_/shut__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 5, 'victory', 'chiến thắng; thắng lợi', 'noun', '[{"en":"The team celebrated their victory with a big dinner.","vi":"Cả đội ăn mừng chiến thắng bằng một bữa tối thịnh soạn."},{"en":"It was an easy victory for our school''s basketball team.","vi":"Đó là một chiến thắng dễ dàng cho đội bóng rổ của trường chúng tôi."},{"en":"After years of hard work, passing the exam felt like a real victory.","vi":"Sau nhiều năm nỗ lực, việc thi đỗ giống như một thắng lợi thật sự."}]', '[{"phrase":"easy victory"},{"phrase":"win a victory"},{"phrase":"victory over"},{"phrase":"celebrate a victory"}]', NULL, '/ˈvɪktəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vic/victo/victory__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 6, 'resolve', 'giải quyết; quyết tâm', 'verb', '[{"en":"We need to resolve this problem before the end of the week.","vi":"Chúng ta cần giải quyết vấn đề này trước cuối tuần."},{"en":"The two neighbors finally resolved their argument about the fence.","vi":"Hai người hàng xóm cuối cùng đã giải quyết xong cuộc tranh cãi về hàng rào."},{"en":"She resolved to exercise every morning this year.","vi":"Cô ấy quyết tâm tập thể dục mỗi sáng trong năm nay."}]', '[{"phrase":"resolve a problem"},{"phrase":"resolve an issue"},{"phrase":"resolve a dispute"},{"phrase":"resolve to do something"}]', NULL, '/rɪˈzɑːlv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resol/resolve__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 7, 'critic', 'nhà phê bình; người chỉ trích', 'noun', '[{"en":"The film received excellent reviews from critics.","vi":"Bộ phim nhận được những lời đánh giá rất tốt từ các nhà phê bình."},{"en":"My brother is a food critic for a local newspaper.","vi":"Anh trai tôi là nhà phê bình ẩm thực cho một tờ báo địa phương."},{"en":"Critics of the plan say it will cost too much.","vi":"Những người chỉ trích kế hoạch nói rằng nó sẽ quá tốn kém."}]', '[{"phrase":"food critic"},{"phrase":"film critic"},{"phrase":"harsh critic"},{"phrase":"critics say"}]', 'critic (người) ≠ criticism (lời phê bình)', '/ˈkrɪtɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/criti/critic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 8, 'variable', 'hay thay đổi; không cố định; thất thường', 'adjective', '[{"en":"The weather in the mountains is highly variable.","vi":"Thời tiết ở vùng núi rất hay thay đổi."},{"en":"Hotel prices are variable and depend on the season.","vi":"Giá khách sạn không cố định và phụ thuộc vào mùa."},{"en":"The quality of the food there is quite variable.","vi":"Chất lượng đồ ăn ở đó khá thất thường."}]', '[{"phrase":"highly variable"},{"phrase":"variable costs"},{"phrase":"variable rate"}]', NULL, '/ˈveriəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/varia/variable__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 9, 'enormous', 'rất lớn; khổng lồ', 'adjective', '[{"en":"They live in an enormous house near the river.","vi":"Họ sống trong một ngôi nhà rất lớn gần sông."},{"en":"Moving to a new country made an enormous difference to her life.","vi":"Chuyển đến một đất nước mới đã tạo ra thay đổi rất lớn trong cuộc sống của cô ấy."},{"en":"The waiter brought us an enormous plate of noodles.","vi":"Người phục vụ mang cho chúng tôi một đĩa mì khổng lồ."}]', '[{"phrase":"enormous amount"},{"phrase":"enormous number"},{"phrase":"enormous difference"}]', NULL, '/ɪˈnɔːrməs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eno/enorm/enormous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 10, 'sweet', 'ngọt; dễ thương', 'adjective', '[{"en":"This cake is too sweet for me.","vi":"Cái bánh này quá ngọt đối với tôi."},{"en":"Ripe mangoes have a sweet taste and a lovely smell.","vi":"Xoài chín có vị ngọt và mùi thơm dễ chịu."},{"en":"It was really sweet of you to bring me flowers.","vi":"Bạn thật dễ thương khi mang hoa đến cho tôi."}]', '[{"phrase":"sweet taste"},{"phrase":"sweet smell"},{"phrase":"have a sweet tooth"}]', NULL, '/swiːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swe/sweet/sweet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 11, 'permanent', 'lâu dài; cố định; vĩnh viễn', 'adjective', '[{"en":"After two years, she finally got a permanent job.","vi":"Sau hai năm, cuối cùng cô ấy cũng có được một công việc lâu dài."},{"en":"Are you looking for a temporary or permanent place to live?","vi":"Bạn đang tìm chỗ ở tạm thời hay lâu dài?"},{"en":"Coffee can leave a permanent stain on a white shirt.","vi":"Cà phê có thể để lại vết bẩn vĩnh viễn trên áo sơ mi trắng."}]', '[{"phrase":"permanent job"},{"phrase":"permanent address"},{"phrase":"permanent damage"},{"phrase":"permanent resident"}]', NULL, '/ˈpɜːrmənənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perma/permanent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 12, 'emotion', 'cảm xúc; sự xúc động', 'noun', '[{"en":"He finds it hard to show his emotions.","vi":"Anh ấy thấy khó thể hiện cảm xúc của mình."},{"en":"Her voice was full of emotion when she thanked everyone.","vi":"Giọng cô ấy đầy xúc động khi cảm ơn mọi người."},{"en":"Try not to let your emotions control your decisions.","vi":"Cố gắng đừng để cảm xúc chi phối các quyết định của bạn."}]', '[{"phrase":"full of emotion"},{"phrase":"show emotion"},{"phrase":"express emotions"},{"phrase":"strong emotions"}]', NULL, '/ɪˈməʊʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emo/emoti/emotion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 13, 'pursue', 'theo đuổi; đuổi theo', 'verb', '[{"en":"She left her office job to pursue a career in music.","vi":"Cô ấy bỏ công việc văn phòng để theo đuổi sự nghiệp âm nhạc."},{"en":"You should pursue your dreams while you are young.","vi":"Bạn nên theo đuổi ước mơ khi còn trẻ."},{"en":"The police pursued the stolen car through the city streets.","vi":"Cảnh sát đuổi theo chiếc xe bị đánh cắp qua các con phố trong thành phố."}]', '[{"phrase":"pursue a career"},{"phrase":"pursue a dream"},{"phrase":"pursue a goal"}]', NULL, '/pərˈsuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/pursu/pursue__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 14, 'tall', 'cao', 'adjective', '[{"en":"My son is already taller than me.","vi":"Con trai tôi đã cao hơn tôi rồi."},{"en":"How tall was your brother when he finished high school?","vi":"Anh trai bạn cao bao nhiêu khi học xong trung học?"},{"en":"There are many tall buildings in the city center.","vi":"Có nhiều tòa nhà cao tầng ở trung tâm thành phố."}]', '[{"phrase":"tall building"},{"phrase":"tall tree"},{"phrase":"grow tall"},{"phrase":"tall and thin"}]', 'tall (người, cây, nhà cao) ≠ high (núi, tường, giá cả)', '/tɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tal/tall_/tall__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 15, 'urge', 'thúc giục; kêu gọi; khuyên', 'verb', '[{"en":"My doctor urged me to stop drinking so much coffee.","vi":"Bác sĩ khuyên tôi ngừng uống nhiều cà phê như vậy."},{"en":"Teachers urged students to start studying early for the exam.","vi":"Giáo viên thúc giục học sinh bắt đầu ôn thi sớm."},{"en":"Local officials are urging people to save water this summer.","vi":"Chính quyền địa phương đang kêu gọi người dân tiết kiệm nước vào mùa hè này."}]', '[{"phrase":"urge people to"},{"phrase":"strongly urge"},{"phrase":"urge caution"}]', 'urge somebody to do something', '/ɜːrdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/urg/urge_/urge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 16, 'enemy', 'kẻ thù; kẻ địch', 'noun', '[{"en":"They were best friends, but now they are enemies.","vi":"Họ từng là bạn thân, nhưng giờ lại là kẻ thù."},{"en":"Sugar is the enemy of healthy teeth.","vi":"Đường là kẻ thù của hàm răng khỏe mạnh."},{"en":"Don''t make enemies at work; you may need their help later.","vi":"Đừng gây thù oán ở nơi làm việc; sau này bạn có thể cần họ giúp đỡ."}]', '[{"phrase":"make enemies"},{"phrase":"worst enemy"},{"phrase":"old enemy"},{"phrase":"enemy of"}]', NULL, '/ˈenəmi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ene/enemy/enemy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 17, 'appoint', 'bổ nhiệm; chỉ định', 'verb', '[{"en":"The company appointed a new manager last month.","vi":"Công ty đã bổ nhiệm một quản lý mới vào tháng trước."},{"en":"She was appointed head of the science department.","vi":"Cô ấy được bổ nhiệm làm trưởng bộ môn khoa học."},{"en":"The school will appoint two teachers to organize the trip.","vi":"Nhà trường sẽ chỉ định hai giáo viên tổ chức chuyến đi."}]', '[{"phrase":"appoint a new manager"},{"phrase":"newly appointed"},{"phrase":"appoint a committee"}]', NULL, '/əˈpɔɪnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appoi/appoint__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 18, 'milk', 'sữa', 'noun', '[{"en":"Could you buy some milk on your way home?","vi":"Bạn mua giúp ít sữa trên đường về nhà được không?"},{"en":"I always have a glass of warm milk before bed.","vi":"Tôi luôn uống một ly sữa ấm trước khi đi ngủ."},{"en":"Do you take milk and sugar in your coffee?","vi":"Bạn có cho sữa và đường vào cà phê không?"}]', '[{"phrase":"warm milk"},{"phrase":"fresh milk"},{"phrase":"a glass of milk"},{"phrase":"a carton of milk"}]', 'không đếm được', '/mɪlk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mil/milk_/milk__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 19, 'talent', 'tài năng; năng khiếu; người tài', 'noun', '[{"en":"She has a real talent for drawing.","vi":"Cô ấy thật sự có năng khiếu vẽ."},{"en":"The show gives young people a chance to show their talents.","vi":"Chương trình cho người trẻ cơ hội thể hiện tài năng của mình."},{"en":"Our company is always looking for new talent.","vi":"Công ty chúng tôi luôn tìm kiếm nhân tài mới."}]', '[{"phrase":"talent for"},{"phrase":"natural talent"},{"phrase":"hidden talent"},{"phrase":"young talent"}]', NULL, '/ˈtælənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tal/talen/talent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 20, 'smell', 'ngửi thấy; có mùi', 'verb', '[{"en":"The kitchen smells wonderful when my mother bakes bread.","vi":"Căn bếp thơm phức mỗi khi mẹ tôi nướng bánh mì."},{"en":"Can you smell something burning in here?","vi":"Bạn có ngửi thấy mùi gì đang cháy ở đây không?"},{"en":"These old shoes smell terrible, so please throw them away.","vi":"Đôi giày cũ này bốc mùi kinh khủng, nên làm ơn vứt chúng đi."}]', '[{"phrase":"smell good"},{"phrase":"smell bad"},{"phrase":"smell something burning"},{"phrase":"smell of"}]', 'smell + tính từ: smell good (không dùng trạng từ)', '/smel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sme/smell/smell__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 21, 'prior', 'trước; có trước', 'adjective', '[{"en":"No prior experience is needed for this job.","vi":"Công việc này không yêu cầu kinh nghiệm trước đó."},{"en":"Please arrive at the airport two hours prior to departure.","vi":"Vui lòng có mặt ở sân bay hai tiếng trước giờ khởi hành."},{"en":"She had no prior knowledge of the surprise party.","vi":"Cô ấy hoàn toàn không biết trước về bữa tiệc bất ngờ."}]', '[{"phrase":"prior to"},{"phrase":"prior experience"},{"phrase":"prior knowledge"},{"phrase":"prior notice"}]', 'prior to = before (trang trọng hơn)', '/ˈpraɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prior/prior__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 22, 'priority', 'sự ưu tiên; điều ưu tiên', 'noun', '[{"en":"My family has always been my top priority.","vi":"Gia đình luôn là ưu tiên hàng đầu của tôi."},{"en":"Safety is our first priority on every trip.","vi":"An toàn là ưu tiên số một của chúng tôi trong mọi chuyến đi."},{"en":"Older passengers are given priority when getting on the bus.","vi":"Hành khách lớn tuổi được ưu tiên khi lên xe buýt."}]', '[{"phrase":"top priority"},{"phrase":"first priority"},{"phrase":"give priority to"},{"phrase":"high priority"}]', NULL, '/praɪˈɔːrəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prior/priority__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 23, 'online', 'trực tuyến; trên mạng', 'adjective', '[{"en":"Online shopping saves me a lot of time.","vi":"Mua sắm trực tuyến giúp tôi tiết kiệm nhiều thời gian."},{"en":"My daughter is taking an online English course this summer.","vi":"Con gái tôi đang học một khóa tiếng Anh trực tuyến vào mùa hè này."},{"en":"Most banks now offer online services to their customers.","vi":"Hầu hết ngân hàng hiện nay đều cung cấp dịch vụ trực tuyến cho khách hàng."}]', '[{"phrase":"online shopping"},{"phrase":"online course"},{"phrase":"online services"},{"phrase":"go online"}]', NULL, '/ˌɑːnˈlaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/onl/onlin/online__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 24, 'phrase', 'cụm từ; câu nói', 'noun', '[{"en":"Write down any new words and phrases you hear in class.","vi":"Hãy ghi lại những từ và cụm từ mới bạn nghe được trong lớp."},{"en":"Can you explain what this phrase means?","vi":"Bạn có thể giải thích cụm từ này nghĩa là gì không?"},{"en":"Before the trip, I learned a few useful phrases in Japanese.","vi":"Trước chuyến đi, tôi đã học vài câu tiếng Nhật hữu ích."}]', '[{"phrase":"useful phrase"},{"phrase":"common phrase"},{"phrase":"key phrase"}]', NULL, '/freɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phr/phras/phrase__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 25, 'pilot', 'phi công', 'noun', '[{"en":"My uncle has been an airline pilot for twenty years.","vi":"Chú tôi đã làm phi công hãng hàng không được hai mươi năm."},{"en":"The pilot told us to fasten our seat belts.","vi":"Phi công bảo chúng tôi thắt dây an toàn."},{"en":"She dreamed of becoming a pilot when she was a child.","vi":"Hồi nhỏ cô ấy mơ ước trở thành phi công."}]', '[{"phrase":"airline pilot"},{"phrase":"helicopter pilot"},{"phrase":"become a pilot"}]', NULL, '/ˈpaɪlət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pil/pilot/pilot__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 26, 'stable', 'ổn định; vững chắc', 'adjective', '[{"en":"After a few difficult years, he finally has a stable job.","vi":"Sau vài năm khó khăn, cuối cùng anh ấy đã có một công việc ổn định."},{"en":"Make sure the ladder is stable before you climb it.","vi":"Hãy chắc chắn cái thang đã vững trước khi bạn trèo lên."},{"en":"Children need a stable home where they feel safe.","vi":"Trẻ em cần một mái ấm ổn định, nơi chúng cảm thấy an toàn."}]', '[{"phrase":"stable job"},{"phrase":"remain stable"},{"phrase":"stable condition"},{"phrase":"stable relationship"}]', NULL, '/ˈsteɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stabl/stable__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 27, 'merely', 'chỉ; chỉ là', 'adverb', '[{"en":"I was merely asking a question; I didn''t mean to upset you.","vi":"Tôi chỉ hỏi một câu thôi; tôi không có ý làm bạn buồn."},{"en":"The trip is not merely a holiday but also a chance to learn.","vi":"Chuyến đi không chỉ là một kỳ nghỉ mà còn là cơ hội để học hỏi."},{"en":"It was merely a small mistake, so don''t worry about it.","vi":"Đó chỉ là một lỗi nhỏ thôi, nên đừng lo lắng về nó."}]', '[{"phrase":"not merely"},{"phrase":"merely because"},{"phrase":"merely a matter of"}]', 'merely = only (trang trọng hơn)', '/ˈmɪrli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mer/merel/merely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 28, 'resolution', 'quyết tâm; sự giải quyết; độ phân giải', 'noun', '[{"en":"My New Year''s resolution is to read one book every month.","vi":"Quyết tâm năm mới của tôi là đọc một cuốn sách mỗi tháng."},{"en":"Both sides are hoping for a quick resolution to the problem.","vi":"Cả hai bên đều mong vấn đề sớm được giải quyết."},{"en":"This new phone takes photos with very high resolution.","vi":"Chiếc điện thoại mới này chụp ảnh với độ phân giải rất cao."}]', '[{"phrase":"New Year''s resolution"},{"phrase":"make a resolution"},{"phrase":"high resolution"}]', NULL, '/ˌrezəˈluːʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resol/resolution__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 29, 'communicate', 'giao tiếp; truyền đạt; liên lạc', 'verb', '[{"en":"We mostly communicate by email because we live in different countries.","vi":"Chúng tôi chủ yếu liên lạc qua email vì sống ở những nước khác nhau."},{"en":"Good managers communicate their ideas clearly to the team.","vi":"Những người quản lý giỏi truyền đạt ý tưởng của mình rõ ràng cho cả nhóm."},{"en":"Babies communicate with their parents by crying and smiling.","vi":"Trẻ sơ sinh giao tiếp với bố mẹ bằng cách khóc và cười."}]', '[{"phrase":"communicate with"},{"phrase":"communicate clearly"},{"phrase":"communicate effectively"}]', NULL, '/kəˈmjuːnɪkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/communicate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-10', 30, 'injury', 'chấn thương; vết thương', 'noun', '[{"en":"He missed three games because of a knee injury.","vi":"Anh ấy vắng mặt ba trận đấu vì chấn thương đầu gối."},{"en":"Luckily, nobody suffered serious injuries in the accident.","vi":"May mắn là không ai bị thương nặng trong vụ tai nạn."},{"en":"Always warm up before running to avoid injury.","vi":"Luôn khởi động trước khi chạy để tránh chấn thương."}]', '[{"phrase":"serious injury"},{"phrase":"knee injury"},{"phrase":"suffer an injury"},{"phrase":"avoid injury"}]', NULL, '/ˈɪndʒəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inj/injur/injury__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-13', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 13', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 13);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 1, 'mechanism', 'cơ chế; bộ phận máy', 'noun', '[{"en":"The company has no mechanism for dealing with customer complaints.","vi":"Công ty không có cơ chế nào để xử lý khiếu nại của khách hàng."},{"en":"Scientists are still studying the mechanism that controls our sleep.","vi":"Các nhà khoa học vẫn đang nghiên cứu cơ chế điều khiển giấc ngủ của chúng ta."},{"en":"The locking mechanism on this door is broken again.","vi":"Bộ phận khóa của cánh cửa này lại bị hỏng rồi."}]', '[{"phrase":"mechanism for"},{"phrase":"locking mechanism"},{"phrase":"control mechanism"}]', NULL, '/ˈmekənɪzəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mec/mecha/mechanism__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 2, 'coat', 'áo khoác; lớp (sơn)', 'noun', '[{"en":"Put on your coat, because it''s freezing outside.","vi":"Mặc áo khoác vào đi, vì ngoài trời lạnh cóng."},{"en":"She hung her wet coat on the hook by the door.","vi":"Cô ấy treo chiếc áo khoác ướt lên móc cạnh cửa."},{"en":"The fence needs another coat of paint before winter.","vi":"Hàng rào cần sơn thêm một lớp nữa trước mùa đông."}]', '[{"phrase":"winter coat"},{"phrase":"put on a coat"},{"phrase":"coat of paint"}]', NULL, '/kəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coa/coat_/coat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 3, 'democracy', 'nền dân chủ; chế độ dân chủ', 'noun', '[{"en":"Free elections are an important part of any democracy.","vi":"Bầu cử tự do là một phần quan trọng của bất kỳ nền dân chủ nào."},{"en":"Our history teacher explained how democracy began in ancient Greece.","vi":"Thầy dạy sử của chúng tôi giải thích nền dân chủ đã ra đời như thế nào ở Hy Lạp cổ đại."},{"en":"Many people believe that democracy works best when citizens are well informed.","vi":"Nhiều người tin rằng chế độ dân chủ vận hành tốt nhất khi người dân được cung cấp đầy đủ thông tin."}]', '[{"phrase":"modern democracy"},{"phrase":"parliamentary democracy"},{"phrase":"democracy works"}]', NULL, '/dɪˈmɑːkrəsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/democ/democracy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 4, 'pocket', 'túi (quần, áo)', 'noun', '[{"en":"I found some old coins in my jacket pocket.","vi":"Tôi tìm thấy vài đồng xu cũ trong túi áo khoác."},{"en":"He just stood there with his hands in his pockets.","vi":"Anh ấy chỉ đứng đó, hai tay đút túi quần."},{"en":"Don''t keep your phone in your back pocket on the bus.","vi":"Đừng để điện thoại trong túi quần sau khi đi xe buýt."}]', '[{"phrase":"back pocket"},{"phrase":"jacket pocket"},{"phrase":"hands in your pockets"}]', NULL, '/ˈpɑːkɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poc/pocke/pocket__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 5, 'lucky', 'may mắn', 'adjective', '[{"en":"We were lucky to find a parking space so close.","vi":"Chúng tôi thật may mắn khi tìm được chỗ đậu xe gần như vậy."},{"en":"Seven has always been my lucky number, so I chose it.","vi":"Số bảy luôn là con số may mắn của tôi, nên tôi đã chọn nó."},{"en":"You''re lucky that nobody was hurt in the accident.","vi":"Bạn may mắn là không ai bị thương trong vụ tai nạn."}]', '[{"phrase":"lucky number"},{"phrase":"feel lucky"},{"phrase":"get lucky"},{"phrase":"lucky to"}]', NULL, '/ˈlʌki/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/luc/lucky/lucky__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 6, 'crash', 'vụ va chạm, tai nạn (xe, máy bay); sự sập (máy tính)', 'noun', '[{"en":"Two people were injured in a car crash last night.","vi":"Hai người bị thương trong một vụ tai nạn ô tô tối qua."},{"en":"Luckily, the driver walked away from the crash without a scratch.","vi":"May mắn thay, người lái xe thoát khỏi vụ va chạm mà không bị trầy xước gì."},{"en":"I lost my whole essay after a computer crash.","vi":"Tôi mất toàn bộ bài luận sau khi máy tính bị sập."}]', '[{"phrase":"car crash"},{"phrase":"plane crash"},{"phrase":"computer crash"}]', NULL, '/kræʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cra/crash/crash__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 7, 'observation', 'sự quan sát, theo dõi; nhận xét', 'noun', '[{"en":"The patient stayed in the hospital overnight for observation.","vi":"Bệnh nhân ở lại bệnh viện qua đêm để theo dõi."},{"en":"Children learn a lot through careful observation of adults.","vi":"Trẻ em học được nhiều điều nhờ quan sát kỹ người lớn."},{"en":"She made an interesting observation about the new office layout.","vi":"Cô ấy đưa ra một nhận xét thú vị về cách bố trí văn phòng mới."}]', '[{"phrase":"make an observation"},{"phrase":"careful observation"},{"phrase":"under observation"}]', NULL, '/ˌɑːbzərˈveɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obs/obser/observation__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 8, 'meat', 'thịt', 'noun', '[{"en":"I don''t eat much meat, but I love fish.","vi":"Tôi không ăn nhiều thịt, nhưng tôi rất thích cá."},{"en":"Cook the meat slowly over low heat until it''s soft.","vi":"Nấu thịt từ từ ở lửa nhỏ cho đến khi mềm."},{"en":"Fresh meat is sold at the market every morning.","vi":"Thịt tươi được bán ở chợ mỗi sáng."}]', '[{"phrase":"red meat"},{"phrase":"fresh meat"},{"phrase":"eat meat"}]', 'Thường không đếm được', '/miːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/meat_/meat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 9, 'concentration', 'sự tập trung; nồng độ', 'noun', '[{"en":"I lost concentration for a moment and missed the turn.","vi":"Tôi mất tập trung một chút và đi lỡ chỗ rẽ."},{"en":"This job requires a lot of patience and concentration.","vi":"Công việc này đòi hỏi nhiều sự kiên nhẫn và tập trung."},{"en":"The water in this lake has a high concentration of salt.","vi":"Nước trong hồ này có nồng độ muối cao."}]', '[{"phrase":"lose concentration"},{"phrase":"high concentration"},{"phrase":"powers of concentration"}]', NULL, '/ˌkɑːnsnˈtreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcentration__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 10, 'implication', 'hệ quả, tác động (có thể xảy ra); hàm ý', 'noun', '[{"en":"We need to think about the implications of this decision.","vi":"Chúng ta cần nghĩ đến những hệ quả của quyết định này."},{"en":"The new law will have serious implications for small businesses.","vi":"Luật mới sẽ có tác động nghiêm trọng đến các doanh nghiệp nhỏ."},{"en":"I didn''t like the implication that I was lying.","vi":"Tôi không thích cái hàm ý rằng tôi đang nói dối."}]', '[{"phrase":"serious implications"},{"phrase":"implications for"},{"phrase":"financial implications"}]', 'Thường dùng số nhiều: implications', '/ˌɪmplɪˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impli/implication__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 11, 'deserve', 'xứng đáng; đáng được', 'verb', '[{"en":"You worked really hard, so you deserve a break.","vi":"Bạn đã làm việc rất chăm chỉ nên bạn xứng đáng được nghỉ ngơi."},{"en":"I think everyone deserves a second chance to get it right.","vi":"Tôi nghĩ ai cũng đáng được có cơ hội thứ hai để làm cho đúng."},{"en":"The team played well and deserved to win the game.","vi":"Đội đã chơi tốt và xứng đáng giành chiến thắng."}]', '[{"phrase":"deserve a break"},{"phrase":"deserve a chance"},{"phrase":"deserve to win"},{"phrase":"deserve better"}]', NULL, '/dɪˈzɜːrv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/deser/deserve__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 12, 'unusual', 'bất thường; khác thường, lạ', 'adjective', '[{"en":"It''s unusual for him to be late for work.","vi":"Việc anh ấy đi làm muộn là điều bất thường."},{"en":"People often ask me about my unusual name.","vi":"Mọi người thường hỏi tôi về cái tên lạ của tôi."},{"en":"The weather has been unusual this year, with very little rain.","vi":"Thời tiết năm nay thật bất thường, rất ít mưa."}]', '[{"phrase":"unusual for"},{"phrase":"highly unusual"},{"phrase":"nothing unusual"}]', NULL, '/ʌnˈjuːʒuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unu/unusu/unusual__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 13, 'defend', 'bảo vệ; bênh vực; phòng thủ', 'verb', '[{"en":"Mother birds will defend their nests against larger animals.","vi":"Chim mẹ sẽ bảo vệ tổ của mình trước những con vật lớn hơn."},{"en":"He always defends his little sister when other kids tease her.","vi":"Cậu ấy luôn bênh vực em gái khi bọn trẻ khác trêu chọc cô bé."},{"en":"Our team needs to defend better in the second half.","vi":"Đội chúng ta cần phòng ngự tốt hơn trong hiệp hai."}]', '[{"phrase":"defend yourself"},{"phrase":"defend against"},{"phrase":"defend a decision"}]', NULL, '/dɪˈfend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defen/defend__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 14, 'classic', 'kinh điển; điển hình; cổ điển (kiểu dáng)', 'adjective', '[{"en":"We watched a classic film from the 1950s last night.","vi":"Tối qua chúng tôi xem một bộ phim kinh điển từ thập niên 1950."},{"en":"That''s a classic example of poor planning.","vi":"Đó là một ví dụ điển hình của việc lên kế hoạch kém."},{"en":"She prefers classic clothes that never go out of style.","vi":"Cô ấy thích quần áo kiểu dáng cổ điển, không bao giờ lỗi mốt."}]', '[{"phrase":"classic example"},{"phrase":"classic film"},{"phrase":"classic case"}]', 'classic ≠ classical (nhạc cổ điển: classical music)', '/ˈklæsɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/class/classic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 15, 'king', 'vua', 'noun', '[{"en":"The king lived in a huge castle by the sea.","vi":"Nhà vua sống trong một lâu đài rộng lớn bên bờ biển."},{"en":"In chess, you win by trapping the other player''s king.","vi":"Trong cờ vua, bạn thắng bằng cách vây bắt quân vua của đối phương."},{"en":"My son loves stories about brave kings and queens.","vi":"Con trai tôi rất thích những câu chuyện về các vị vua và nữ hoàng dũng cảm."}]', '[{"phrase":"king and queen"},{"phrase":"become king"},{"phrase":"the King of"}]', NULL, '/kɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kin/king_/king__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 16, 'interaction', 'sự tương tác; sự giao tiếp', 'noun', '[{"en":"Online classes offer less interaction between teachers and students.","vi":"Các lớp học trực tuyến có ít sự tương tác giữa giáo viên và học sinh hơn."},{"en":"Young children need daily interaction with other kids their age.","vi":"Trẻ nhỏ cần được giao tiếp hằng ngày với những đứa trẻ cùng tuổi."},{"en":"Your doctor will check for interactions between different medicines.","vi":"Bác sĩ sẽ kiểm tra sự tương tác giữa các loại thuốc khác nhau."}]', '[{"phrase":"social interaction"},{"phrase":"interaction between"},{"phrase":"interaction with"},{"phrase":"face-to-face interaction"}]', NULL, '/ˌɪntərˈækʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interaction__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 17, 'repair', 'sửa chữa', 'verb', '[{"en":"How much will it cost to repair the roof?","vi":"Sửa mái nhà sẽ tốn bao nhiêu tiền?"},{"en":"My dad repaired my bike in less than an hour.","vi":"Bố tôi sửa xe đạp cho tôi chưa đến một tiếng."},{"en":"The road is closed while workers repair the bridge.","vi":"Con đường bị phong tỏa trong lúc công nhân sửa cây cầu."}]', '[{"phrase":"repair damage"},{"phrase":"repair the roof"},{"phrase":"get something repaired"}]', NULL, '/rɪˈper/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repai/repair__us_7.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 18, 'collapse', 'sụp đổ, đổ sập; ngã quỵ', 'verb', '[{"en":"The old bridge collapsed during the storm last night.","vi":"Cây cầu cũ bị sập trong cơn bão tối qua."},{"en":"After the long race, he collapsed onto the grass.","vi":"Sau cuộc đua dài, anh ấy ngã quỵ xuống bãi cỏ."},{"en":"Their small business collapsed after only two years.","vi":"Công việc kinh doanh nhỏ của họ sụp đổ chỉ sau hai năm."}]', '[{"phrase":"collapse completely"},{"phrase":"roof collapsed"},{"phrase":"business collapsed"}]', NULL, '/kəˈlæps/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colla/collapse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 19, 'borrow', 'mượn; vay', 'verb', '[{"en":"Can I borrow your pen for a minute?","vi":"Mình mượn bút của bạn một lát được không?"},{"en":"We had to borrow money from the bank to buy the house.","vi":"Chúng tôi đã phải vay tiền ngân hàng để mua nhà."},{"en":"She borrowed three books from the library last week.","vi":"Tuần trước cô ấy đã mượn ba cuốn sách ở thư viện."}]', '[{"phrase":"borrow money"},{"phrase":"borrow from"},{"phrase":"borrow a book"}]', 'borrow (mượn) ≠ lend (cho mượn)', '/ˈbɔːrəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bor/borro/borrow__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 20, 'fundamental', 'cơ bản, căn bản; nền tảng', 'adjective', '[{"en":"Clean water is a fundamental human need.","vi":"Nước sạch là một nhu cầu cơ bản của con người."},{"en":"There is a fundamental difference between our two plans.","vi":"Có một sự khác biệt căn bản giữa hai kế hoạch của chúng ta."},{"en":"Reading is fundamental to success in every subject at school.","vi":"Việc đọc là nền tảng để học tốt mọi môn ở trường."}]', '[{"phrase":"fundamental difference"},{"phrase":"fundamental change"},{"phrase":"fundamental to"},{"phrase":"fundamental rights"}]', NULL, '/ˌfʌndəˈmentl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funda/fundamental__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 21, 'dish', 'món ăn; đĩa, bát đĩa', 'noun', '[{"en":"Pho is probably the most famous Vietnamese dish.","vi":"Phở có lẽ là món ăn Việt Nam nổi tiếng nhất."},{"en":"Whose turn is it to wash the dishes tonight?","vi":"Tối nay đến lượt ai rửa bát đĩa?"},{"en":"Put the salad in a large dish and serve it cold.","vi":"Cho món salad vào một chiếc đĩa lớn và dùng lạnh."}]', '[{"phrase":"wash the dishes"},{"phrase":"do the dishes"},{"phrase":"main dish"},{"phrase":"side dish"}]', NULL, '/dɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dish_/dish__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 22, 'abroad', 'ở nước ngoài; ra nước ngoài', 'adverb', '[{"en":"My sister is planning to study abroad next year.","vi":"Chị gái tôi đang dự định đi du học vào năm tới."},{"en":"Have you ever traveled abroad on your own?","vi":"Bạn đã bao giờ tự mình đi nước ngoài chưa?"},{"en":"Many young people go abroad to find better jobs.","vi":"Nhiều người trẻ ra nước ngoài để tìm việc làm tốt hơn."}]', '[{"phrase":"study abroad"},{"phrase":"travel abroad"},{"phrase":"go abroad"},{"phrase":"live abroad"}]', 'Không dùng "to": go abroad (không nói go to abroad)', '/əˈbrɔːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abr/abroa/abroad__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 23, 'soul', 'tâm hồn; linh hồn; người (không một ai)', 'noun', '[{"en":"A quiet walk in nature is good for the soul.","vi":"Một buổi đi dạo yên tĩnh giữa thiên nhiên rất tốt cho tâm hồn."},{"en":"She puts her heart and soul into everything she does.","vi":"Cô ấy dồn hết tâm huyết vào mọi việc mình làm."},{"en":"It was so late that there wasn''t a soul on the street.","vi":"Trời đã khuya đến mức trên phố không có một bóng người."}]', '[{"phrase":"heart and soul"},{"phrase":"not a soul"},{"phrase":"good for the soul"}]', NULL, '/səʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/soul_/soul__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 24, 'capable', 'có khả năng; có năng lực, giỏi', 'adjective', '[{"en":"I''m sure you''re capable of doing this job well.","vi":"Tôi chắc chắn bạn có đủ khả năng làm tốt công việc này."},{"en":"She is a very capable manager, and everyone trusts her.","vi":"Cô ấy là một người quản lý rất có năng lực, và ai cũng tin tưởng cô ấy."},{"en":"This car is capable of reaching very high speeds.","vi":"Chiếc xe này có thể đạt tốc độ rất cao."}]', '[{"phrase":"capable of"},{"phrase":"highly capable"},{"phrase":"perfectly capable"}]', 'capable of + V-ing', '/ˈkeɪpəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capab/capable__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 25, 'defeat', 'đánh bại; thắng', 'verb', '[{"en":"Our school team defeated last year''s champions in the final.","vi":"Đội trường chúng tôi đã đánh bại nhà vô địch năm ngoái trong trận chung kết."},{"en":"She defeated all the other players in the chess competition.","vi":"Cô ấy đã thắng tất cả những người chơi khác trong cuộc thi cờ vua."},{"en":"They were defeated three times before they finally won a game.","vi":"Họ đã bị đánh bại ba lần trước khi cuối cùng thắng được một trận."}]', '[{"phrase":"defeat an opponent"},{"phrase":"easily defeat"},{"phrase":"narrowly defeated"}]', NULL, '/dɪˈfiːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defea/defeat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 26, 'presidential', '(thuộc) tổng thống', 'adjective', '[{"en":"The presidential election takes place every four years.","vi":"Cuộc bầu cử tổng thống diễn ra bốn năm một lần."},{"en":"Crowds gathered outside the presidential palace to watch the ceremony.","vi":"Đám đông tụ tập bên ngoài dinh tổng thống để xem buổi lễ."},{"en":"Both presidential candidates will appear on TV tonight.","vi":"Cả hai ứng cử viên tổng thống sẽ xuất hiện trên truyền hình tối nay."}]', '[{"phrase":"presidential election"},{"phrase":"presidential candidate"},{"phrase":"presidential campaign"}]', NULL, '/ˌprezɪˈdenʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/presi/presidential__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 27, 'perfectly', 'hoàn hảo; hoàn toàn', 'adverb', '[{"en":"These shoes fit me perfectly, so I bought two pairs.","vi":"Đôi giày này vừa khít với chân tôi nên tôi đã mua hai đôi."},{"en":"It''s perfectly normal to feel nervous before an exam.","vi":"Cảm thấy lo lắng trước kỳ thi là hoàn toàn bình thường."},{"en":"He speaks English perfectly, but he has never lived abroad.","vi":"Anh ấy nói tiếng Anh hoàn hảo, dù chưa từng sống ở nước ngoài."}]', '[{"phrase":"perfectly normal"},{"phrase":"fit perfectly"},{"phrase":"perfectly clear"},{"phrase":"work perfectly"}]', NULL, '/ˈpɜːrfɪktli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perfe/perfectly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 28, 'enhance', 'nâng cao; làm tăng (chất lượng, giá trị)', 'verb', '[{"en":"A little lemon juice will enhance the flavor of the fish.","vi":"Một chút nước cốt chanh sẽ làm tăng hương vị của món cá."},{"en":"Taking this course could enhance your chances of getting a job.","vi":"Tham gia khóa học này có thể nâng cao cơ hội tìm được việc làm của bạn."},{"en":"Good lighting can greatly enhance the look of a room.","vi":"Ánh sáng tốt có thể làm căn phòng trông đẹp hơn rất nhiều."}]', '[{"phrase":"greatly enhance"},{"phrase":"enhance the quality"},{"phrase":"enhance performance"},{"phrase":"enhance your chances"}]', NULL, '/ɪnˈhæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enh/enhan/enhance__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 29, 'proud', 'tự hào; kiêu hãnh', 'adjective', '[{"en":"My parents were very proud of me when I graduated.","vi":"Bố mẹ tôi rất tự hào về tôi khi tôi tốt nghiệp."},{"en":"You should be proud of what you''ve achieved this year.","vi":"Bạn nên tự hào về những gì mình đã đạt được trong năm nay."},{"en":"He was too proud to ask anyone for help.","vi":"Anh ấy quá kiêu hãnh nên không chịu nhờ ai giúp đỡ."}]', '[{"phrase":"proud of"},{"phrase":"feel proud"},{"phrase":"proud moment"}]', 'be proud of sb/sth', '/praʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proud/proud__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-13', 30, 'emergency', 'tình trạng khẩn cấp; trường hợp cấp cứu', 'noun', '[{"en":"In an emergency, call this number right away.","vi":"Trong trường hợp khẩn cấp, hãy gọi ngay số này."},{"en":"The plane had to make an emergency landing in a field.","vi":"Chiếc máy bay đã phải hạ cánh khẩn cấp xuống một cánh đồng."},{"en":"She was taken to the emergency room after falling off her bike.","vi":"Cô ấy được đưa vào phòng cấp cứu sau khi ngã xe đạp."}]', '[{"phrase":"in an emergency"},{"phrase":"emergency room"},{"phrase":"emergency exit"},{"phrase":"medical emergency"}]', NULL, '/ɪˈmɜːrdʒənsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eme/emerg/emergency__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-14', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 14', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 14);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 1, 'educational', 'mang tính giáo dục; (thuộc) giáo dục', 'adjective', '[{"en":"My kids watch an educational show about animals every morning.","vi":"Các con tôi xem một chương trình giáo dục về động vật mỗi sáng."},{"en":"The trip to the science museum was fun and very educational.","vi":"Chuyến đi đến bảo tàng khoa học vừa vui vừa rất bổ ích."},{"en":"She works for an educational organization that helps poor children.","vi":"Cô ấy làm việc cho một tổ chức giáo dục giúp đỡ trẻ em nghèo."}]', '[{"phrase":"educational system"},{"phrase":"educational games"},{"phrase":"educational value"},{"phrase":"educational background"}]', NULL, '/ˌedʒuˈkeɪʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edu/educa/educational__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 2, 'distinguish', 'phân biệt; nhận ra', 'verb', '[{"en":"Young children often can''t distinguish between right and wrong.","vi":"Trẻ nhỏ thường không phân biệt được đúng và sai."},{"en":"It''s hard to distinguish the twins because they look so alike.","vi":"Thật khó phân biệt hai đứa sinh đôi vì chúng trông rất giống nhau."},{"en":"In the dark, I could barely distinguish the shape of the house.","vi":"Trong bóng tối, tôi hầu như không nhận ra được hình dáng ngôi nhà."}]', '[{"phrase":"distinguish between"},{"phrase":"distinguish something from something"},{"phrase":"clearly distinguish"}]', 'distinguish A from B / distinguish between A and B', '/dɪˈstɪŋɡwɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disti/distinguish__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 3, 'substantial', 'đáng kể; lớn', 'adjective', '[{"en":"He received a substantial pay raise after his first year.","vi":"Anh ấy được tăng lương đáng kể sau năm đầu tiên."},{"en":"The storm caused substantial damage to homes along the coast.","vi":"Cơn bão gây thiệt hại đáng kể cho nhà cửa dọc bờ biển."},{"en":"We need a substantial amount of money to fix the roof.","vi":"Chúng tôi cần một khoản tiền lớn để sửa mái nhà."}]', '[{"phrase":"substantial amount"},{"phrase":"substantial increase"},{"phrase":"substantial damage"},{"phrase":"substantial number"}]', NULL, '/səbˈstænʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subst/substantial__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 4, 'nearby', 'gần đó; ở gần', 'adjective', '[{"en":"We had lunch at a nearby café before the movie.","vi":"Chúng tôi ăn trưa ở một quán cà phê gần đó trước khi xem phim."},{"en":"Is there a pharmacy nearby where I can buy some medicine?","vi":"Có hiệu thuốc nào ở gần đây để tôi mua thuốc không?"},{"en":"Students from nearby towns take the bus to this school.","vi":"Học sinh từ các thị trấn lân cận đi xe buýt đến trường này."}]', '[{"phrase":"nearby town"},{"phrase":"nearby village"},{"phrase":"live nearby"}]', 'Cũng dùng làm trạng từ: live nearby', '/ˌnɪrˈbaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nea/nearb/nearby__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 5, 'manufacturer', 'nhà sản xuất; hãng sản xuất', 'noun', '[{"en":"If the phone breaks, send it back to the manufacturer.","vi":"Nếu điện thoại bị hỏng, hãy gửi nó lại cho nhà sản xuất."},{"en":"My uncle works for a large car manufacturer in Japan.","vi":"Chú tôi làm việc cho một hãng sản xuất ô tô lớn ở Nhật Bản."},{"en":"Always follow the manufacturer''s instructions when using this machine.","vi":"Luôn làm theo hướng dẫn của nhà sản xuất khi sử dụng máy này."}]', '[{"phrase":"car manufacturer"},{"phrase":"leading manufacturer"},{"phrase":"manufacturer''s instructions"}]', NULL, '/ˌmænjuˈfæktʃərər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manuf/manufacturer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 6, 'slide', 'trượt; lướt; luồn', 'verb', '[{"en":"The kids love to slide down the snowy hill on plastic bags.","vi":"Bọn trẻ rất thích trượt xuống đồi tuyết trên những chiếc túi nhựa."},{"en":"She slid the letter under the door and walked away.","vi":"Cô ấy luồn lá thư qua khe cửa rồi bỏ đi."},{"en":"The door slides open when you step in front of it.","vi":"Cánh cửa tự trượt mở khi bạn bước tới trước nó."}]', '[{"phrase":"slide down"},{"phrase":"slide open"},{"phrase":"slide into"},{"phrase":"sliding door"}]', 'slide – slid – slid', '/slaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/slide/slide__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 7, 'valuable', 'có giá trị; quý giá', 'adjective', '[{"en":"Don''t leave anything valuable in your car overnight.","vi":"Đừng để bất cứ thứ gì có giá trị trong xe qua đêm."},{"en":"Working in a hotel gave me valuable experience with customers.","vi":"Làm việc ở khách sạn đã cho tôi kinh nghiệm quý giá khi tiếp xúc với khách hàng."},{"en":"Thank you for your time; I know it''s very valuable.","vi":"Cảm ơn bạn đã dành thời gian; tôi biết thời gian của bạn rất quý."}]', '[{"phrase":"valuable experience"},{"phrase":"valuable information"},{"phrase":"valuable time"},{"phrase":"extremely valuable"}]', NULL, '/ˈvæljuəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/val/valua/valuable__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 8, 'personally', 'về phần cá nhân; đích thân; trực tiếp', 'adverb', '[{"en":"Personally, I prefer the beach to the mountains.","vi":"Cá nhân tôi thì thích biển hơn núi."},{"en":"The manager came personally to apologize for the mistake.","vi":"Người quản lý đã đích thân đến xin lỗi về sai sót đó."},{"en":"I''ve never met her personally, but we often talk online.","vi":"Tôi chưa bao giờ gặp trực tiếp cô ấy, nhưng chúng tôi hay nói chuyện trên mạng."}]', '[{"phrase":"personally responsible"},{"phrase":"know someone personally"},{"phrase":"take it personally"}]', 'take something personally: để bụng, cho là nhắm vào mình', '/ˈpɜːrsənəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/personally__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 9, 'breast', 'ngực; vú; ức (gà)', 'noun', '[{"en":"I bought some chicken breast to make a salad for dinner.","vi":"Tôi mua một ít ức gà để làm món salad cho bữa tối."},{"en":"Doctors say breast milk is the best food for babies.","vi":"Các bác sĩ nói sữa mẹ là thức ăn tốt nhất cho trẻ sơ sinh."},{"en":"The small bird had a bright red breast and gray wings.","vi":"Con chim nhỏ có phần ngực màu đỏ tươi và đôi cánh màu xám."}]', '[{"phrase":"chicken breast"},{"phrase":"breast milk"},{"phrase":"breast pocket"}]', NULL, '/brest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/breas/breast__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 10, 'cope', 'đối phó; đương đầu; xoay xở', 'verb', '[{"en":"How do you cope with stress when work gets busy?","vi":"Bạn đối phó với căng thẳng thế nào khi công việc bận rộn?"},{"en":"Living alone in a new country was hard, but she learned to cope.","vi":"Sống một mình ở đất nước mới rất vất vả, nhưng cô ấy đã học được cách xoay xở."},{"en":"The small hospital couldn''t cope with so many patients.","vi":"Bệnh viện nhỏ không thể xoay xở nổi với quá nhiều bệnh nhân."}]', '[{"phrase":"cope with stress"},{"phrase":"cope with pressure"},{"phrase":"learn to cope"},{"phrase":"struggle to cope"}]', 'cope with something', '/kəʊp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cop/cope_/cope__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 11, 'approximately', 'khoảng; xấp xỉ', 'adverb', '[{"en":"The flight takes approximately three hours from here.","vi":"Chuyến bay từ đây mất khoảng ba tiếng."},{"en":"Approximately half of the students live in the city.","vi":"Xấp xỉ một nửa số sinh viên sống trong thành phố."},{"en":"The house was built approximately one hundred years ago.","vi":"Ngôi nhà được xây dựng cách đây khoảng một trăm năm."}]', '[{"phrase":"approximately equal"},{"phrase":"approximately half"},{"phrase":"at approximately"}]', NULL, '/əˈprɑːksɪmətli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approximately__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 12, 'accommodation', 'chỗ ở; nơi ăn ở', 'noun', '[{"en":"The price of the tour includes flights and accommodation.","vi":"Giá tour đã bao gồm vé máy bay và chỗ ở."},{"en":"Finding cheap accommodation near the university is not easy.","vi":"Tìm chỗ ở giá rẻ gần trường đại học không hề dễ."},{"en":"We booked our accommodation online two months before the trip.","vi":"Chúng tôi đặt chỗ ở trên mạng hai tháng trước chuyến đi."}]', '[{"phrase":"find accommodation"},{"phrase":"cheap accommodation"},{"phrase":"hotel accommodation"},{"phrase":"book accommodation"}]', 'Anh: không đếm được (accommodation) · Mỹ: thường dùng accommodations', '/əˌkɑːməˈdeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accommodation__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 13, 'highlight', 'làm nổi bật; nhấn mạnh; tô sáng', 'verb', '[{"en":"The report highlights the need for more teachers in rural areas.","vi":"Bản báo cáo nhấn mạnh nhu cầu cần thêm giáo viên ở vùng nông thôn."},{"en":"Please highlight the important words in yellow.","vi":"Hãy tô sáng những từ quan trọng bằng màu vàng."},{"en":"Her speech highlighted the problems that young workers face today.","vi":"Bài phát biểu của cô ấy làm nổi bật những vấn đề người lao động trẻ gặp phải ngày nay."}]', '[{"phrase":"highlight the need"},{"phrase":"highlight the importance"},{"phrase":"highlight the problem"}]', 'Danh từ: highlight = điểm nổi bật (the highlight of the trip)', '/ˈhaɪlaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hig/highl/highlight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 14, 'reporter', 'phóng viên', 'noun', '[{"en":"A reporter asked the mayor about the new bridge.","vi":"Một phóng viên đã hỏi thị trưởng về cây cầu mới."},{"en":"She worked as a sports reporter for a local newspaper.","vi":"Cô ấy từng làm phóng viên thể thao cho một tờ báo địa phương."},{"en":"Reporters were waiting outside the hospital all night.","vi":"Các phóng viên đã chờ bên ngoài bệnh viện suốt đêm."}]', '[{"phrase":"newspaper reporter"},{"phrase":"TV reporter"},{"phrase":"sports reporter"},{"phrase":"tell reporters"}]', NULL, '/rɪˈpɔːrtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repor/reporter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 15, 'climate', 'khí hậu; tình hình', 'noun', '[{"en":"My grandparents moved south because they wanted a warmer climate.","vi":"Ông bà tôi chuyển xuống phía nam vì muốn sống ở nơi khí hậu ấm hơn."},{"en":"Climate change is making summers hotter every year.","vi":"Biến đổi khí hậu đang khiến mùa hè mỗi năm một nóng hơn."},{"en":"In the current economic climate, many people are afraid to spend money.","vi":"Trong tình hình kinh tế hiện nay, nhiều người ngại tiêu tiền."}]', '[{"phrase":"climate change"},{"phrase":"warm climate"},{"phrase":"economic climate"},{"phrase":"tropical climate"}]', NULL, '/ˈklaɪmət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cli/clima/climate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 16, 'shirt', 'áo sơ mi; áo', 'noun', '[{"en":"He wore a white shirt and a tie to the interview.","vi":"Anh ấy mặc áo sơ mi trắng và thắt cà vạt đi phỏng vấn."},{"en":"Can you iron my shirt while I take a shower?","vi":"Bạn ủi giúp tôi cái áo sơ mi trong lúc tôi tắm được không?"},{"en":"I spilled coffee on my shirt this morning.","vi":"Sáng nay tôi làm đổ cà phê lên áo."}]', '[{"phrase":"wear a shirt"},{"phrase":"white shirt"},{"phrase":"iron a shirt"},{"phrase":"long-sleeved shirt"}]', NULL, '/ʃɜːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/shirt/shirt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 17, 'exception', 'ngoại lệ; trường hợp ngoại lệ', 'noun', '[{"en":"Everyone must arrive by eight, and there are no exceptions.","vi":"Mọi người phải có mặt trước tám giờ, không có ngoại lệ."},{"en":"With the exception of two students, the whole class passed the test.","vi":"Ngoại trừ hai học sinh, cả lớp đều qua bài kiểm tra."},{"en":"We don''t usually allow pets, but we''ll make an exception for you.","vi":"Chúng tôi thường không cho mang thú cưng, nhưng sẽ ngoại lệ cho bạn."}]', '[{"phrase":"make an exception"},{"phrase":"with the exception of"},{"phrase":"no exception"},{"phrase":"exception to the rule"}]', NULL, '/ɪkˈsepʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excep/exception__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 18, 'corporation', 'tập đoàn; công ty lớn', 'noun', '[{"en":"My father worked for a large corporation for thirty years.","vi":"Bố tôi làm việc cho một tập đoàn lớn suốt ba mươi năm."},{"en":"Some people think big corporations should pay more tax.","vi":"Một số người cho rằng các tập đoàn lớn nên đóng thuế nhiều hơn."},{"en":"The corporation plans to open two new factories next year.","vi":"Tập đoàn dự định mở hai nhà máy mới vào năm tới."}]', '[{"phrase":"large corporation"},{"phrase":"multinational corporation"},{"phrase":"big corporations"}]', NULL, '/ˌkɔːrpəˈreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corpo/corporation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 19, 'chip', 'khoai tây chiên; con chip (điện tử); vết mẻ', 'noun', '[{"en":"We ate fish and chips by the sea.","vi":"Chúng tôi ăn cá và khoai tây chiên bên bờ biển."},{"en":"Every new phone has a tiny computer chip inside it.","vi":"Mỗi chiếc điện thoại mới đều có một con chip máy tính nhỏ xíu bên trong."},{"en":"There''s a small chip on the edge of this cup.","vi":"Có một vết mẻ nhỏ trên miệng chiếc cốc này."}]', '[{"phrase":"fish and chips"},{"phrase":"potato chips"},{"phrase":"computer chip"},{"phrase":"chocolate chip"}]', 'Anh: chips = khoai tây chiên que · Mỹ: chips = khoai tây chiên lát mỏng (Anh gọi crisps)', '/tʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/chip_/chip__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 20, 'winner', 'người chiến thắng; người đoạt giải', 'noun', '[{"en":"The winner of the race will get a gold medal.","vi":"Người chiến thắng cuộc đua sẽ nhận được huy chương vàng."},{"en":"They will announce the winners at the end of the evening.","vi":"Họ sẽ công bố những người đoạt giải vào cuối buổi tối."},{"en":"My sister was the lucky winner of a free trip to Paris.","vi":"Chị tôi là người may mắn trúng một chuyến du lịch miễn phí đến Paris."}]', '[{"phrase":"the winner of"},{"phrase":"announce the winner"},{"phrase":"lucky winner"},{"phrase":"prize winner"}]', NULL, '/ˈwɪnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/winne/winner__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 21, 'encounter', 'gặp phải; bắt gặp; cuộc chạm trán', 'verb', '[{"en":"We encountered a few problems when we moved to a new house.","vi":"Chúng tôi gặp phải một vài vấn đề khi chuyển sang nhà mới."},{"en":"Call me if you encounter any difficulties with the software.","vi":"Gọi cho tôi nếu bạn gặp bất kỳ khó khăn nào với phần mềm."},{"en":"I had a strange encounter with a stranger on the train.","vi":"Tôi đã có một cuộc gặp gỡ kỳ lạ với một người lạ trên tàu."}]', '[{"phrase":"encounter problems"},{"phrase":"encounter difficulties"},{"phrase":"chance encounter"}]', NULL, '/ɪnˈkaʊntər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enc/encou/encounter__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 22, 'brown', 'màu nâu; nâu', 'adjective', '[{"en":"She has long brown hair and green eyes.","vi":"Cô ấy có mái tóc dài màu nâu và đôi mắt xanh lục."},{"en":"I usually eat brown rice because it''s healthier.","vi":"Tôi thường ăn gạo lứt vì nó tốt cho sức khỏe hơn."},{"en":"The leaves turn brown and fall in autumn.","vi":"Lá cây chuyển sang màu nâu và rụng vào mùa thu."}]', '[{"phrase":"brown hair"},{"phrase":"brown eyes"},{"phrase":"brown rice"},{"phrase":"turn brown"}]', 'brown rice: gạo lứt; brown bread: bánh mì nâu (nguyên cám)', '/braʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bro/brown/brown__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 23, 'breathe', 'thở; hít thở', 'verb', '[{"en":"Close your eyes and breathe slowly to relax.","vi":"Hãy nhắm mắt lại và thở chậm để thư giãn."},{"en":"It was so smoky in the kitchen that I couldn''t breathe.","vi":"Trong bếp nhiều khói đến mức tôi không thở được."},{"en":"I love breathing the fresh air in the mountains.","vi":"Tôi thích hít thở không khí trong lành trên núi."}]', '[{"phrase":"breathe deeply"},{"phrase":"breathe in"},{"phrase":"breathe out"},{"phrase":"breathe fresh air"}]', 'breathe (v) ≠ breath (n): hơi thở', '/briːð/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/breat/breathe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 24, 'excuse', 'lời bào chữa; cái cớ; lý do', 'noun', '[{"en":"He always has an excuse for being late to work.","vi":"Anh ta lúc nào cũng có cớ cho việc đi làm muộn."},{"en":"Being tired is no excuse for being rude to people.","vi":"Mệt mỏi không phải là lý do để thô lỗ với người khác."},{"en":"She made an excuse and left the party early.","vi":"Cô ấy viện cớ rồi rời bữa tiệc sớm."}]', '[{"phrase":"make an excuse"},{"phrase":"good excuse"},{"phrase":"no excuse for"},{"phrase":"excuse me"}]', 'Danh từ /ɪkˈskjuːs/ · động từ /ɪkˈskjuːz/', '/ɪkˈskjuːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excus/excuse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 25, 'partly', 'một phần; phần nào', 'adverb', '[{"en":"The accident was partly my fault, and I''m sorry.","vi":"Vụ tai nạn một phần là lỗi của tôi, và tôi xin lỗi."},{"en":"Tomorrow will be partly cloudy with a chance of rain.","vi":"Ngày mai trời có mây rải rác và có khả năng mưa."},{"en":"I moved to the city partly because of my job.","vi":"Tôi chuyển lên thành phố một phần là vì công việc."}]', '[{"phrase":"partly because"},{"phrase":"partly responsible"},{"phrase":"partly cloudy"},{"phrase":"partly due to"}]', NULL, '/ˈpɑːrtli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/partl/partly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 26, 'tennis', 'quần vợt; tennis', 'noun', '[{"en":"My brother and I play tennis every Saturday morning.","vi":"Anh trai tôi và tôi chơi quần vợt vào mỗi sáng thứ Bảy."},{"en":"The hotel has a pool and two tennis courts.","vi":"Khách sạn có một hồ bơi và hai sân quần vợt."},{"en":"She started taking tennis lessons when she was six.","vi":"Cô ấy bắt đầu học quần vợt từ năm sáu tuổi."}]', '[{"phrase":"play tennis"},{"phrase":"tennis court"},{"phrase":"tennis player"},{"phrase":"tennis match"}]', 'play tennis (không dùng the)', '/ˈtenɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tenni/tennis__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 27, 'urban', '(thuộc) đô thị; thành thị', 'adjective', '[{"en":"More and more people are moving from villages to urban areas.","vi":"Ngày càng nhiều người chuyển từ làng quê ra các khu đô thị."},{"en":"Traffic is one of the biggest problems of urban life.","vi":"Giao thông là một trong những vấn đề lớn nhất của cuộc sống đô thị."},{"en":"Urban families often live in small apartments.","vi":"Các gia đình ở thành thị thường sống trong những căn hộ nhỏ."}]', '[{"phrase":"urban areas"},{"phrase":"urban life"},{"phrase":"urban population"},{"phrase":"urban development"}]', 'urban ≠ rural (nông thôn)', '/ˈɜːrbən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/urb/urban/urban__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 28, 'confuse', 'làm bối rối; nhầm lẫn', 'verb', '[{"en":"The new instructions only confused me more.","vi":"Hướng dẫn mới chỉ càng làm tôi bối rối hơn."},{"en":"People often confuse me with my twin sister.","vi":"Mọi người hay nhầm tôi với chị em sinh đôi của tôi."},{"en":"Don''t confuse the words ''desert'' and ''dessert'' in your essay.","vi":"Đừng nhầm lẫn hai từ ''desert'' và ''dessert'' trong bài luận của bạn."}]', '[{"phrase":"confuse A with B"},{"phrase":"get confused"},{"phrase":"confuse the issue"}]', 'confuse A with B: nhầm A với B', '/kənˈfjuːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfuse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 29, 'southern', '(thuộc) phía nam; miền Nam', 'adjective', '[{"en":"We spent our holiday on a beach in southern Thailand.","vi":"Chúng tôi đã nghỉ lễ ở một bãi biển phía nam Thái Lan."},{"en":"The southern part of the country is hot all year.","vi":"Phần phía nam của đất nước nóng quanh năm."},{"en":"My friend speaks with a strong southern accent.","vi":"Bạn tôi nói giọng miền Nam rất đặc trưng."}]', '[{"phrase":"southern part"},{"phrase":"southern coast"},{"phrase":"southern accent"},{"phrase":"southern border"}]', NULL, '/ˈsʌðərn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/south/southern__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-14', 30, 'output', 'sản lượng; đầu ra', 'noun', '[{"en":"The factory''s output has doubled since last year.","vi":"Sản lượng của nhà máy đã tăng gấp đôi kể từ năm ngoái."},{"en":"Rice output was low this year because of the dry weather.","vi":"Sản lượng lúa năm nay thấp do thời tiết khô hạn."},{"en":"Check the output of the program to see if there are any errors.","vi":"Hãy kiểm tra đầu ra của chương trình để xem có lỗi nào không."}]', '[{"phrase":"increase output"},{"phrase":"total output"},{"phrase":"industrial output"},{"phrase":"power output"}]', NULL, '/ˈaʊtpʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outpu/output__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-15', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 15', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 15);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 1, 'beauty', 'vẻ đẹp; cái đẹp', 'noun', '[{"en":"We stopped the car to enjoy the beauty of the mountains.","vi":"Chúng tôi dừng xe để ngắm vẻ đẹp của núi non."},{"en":"Her paintings capture the simple beauty of everyday life.","vi":"Những bức tranh của cô ấy ghi lại vẻ đẹp giản dị của cuộc sống thường ngày."},{"en":"This old town is famous for its natural beauty and quiet streets.","vi":"Thị trấn cổ này nổi tiếng với vẻ đẹp tự nhiên và những con phố yên tĩnh."}]', '[{"phrase":"natural beauty"},{"phrase":"great beauty"},{"phrase":"the beauty of"}]', NULL, '/ˈbjuːti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/beaut/beauty__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 2, 'massive', 'to lớn; đồ sộ', 'adjective', '[{"en":"A massive tree fell across the road during the storm.","vi":"Một cái cây to lớn đổ chắn ngang đường trong cơn bão."},{"en":"The new shopping center is massive, so wear comfortable shoes.","vi":"Trung tâm mua sắm mới rất đồ sộ, nên hãy mang giày thoải mái."},{"en":"Moving to another country was a massive change for our family.","vi":"Chuyển sang nước khác là một thay đổi to lớn đối với gia đình chúng tôi."}]', '[{"phrase":"massive amount"},{"phrase":"massive change"},{"phrase":"massive building"}]', NULL, '/ˈmæsɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mas/massi/massive__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 3, 'install', 'lắp đặt; cài đặt', 'verb', '[{"en":"We''re having a new air conditioner installed next week.","vi":"Tuần sau chúng tôi sẽ cho lắp đặt một máy điều hòa mới."},{"en":"You need to install the app before you can join the meeting.","vi":"Bạn cần cài đặt ứng dụng trước khi có thể tham gia cuộc họp."},{"en":"My dad installed a small camera above the front door.","vi":"Bố tôi đã lắp một chiếc camera nhỏ phía trên cửa trước."}]', '[{"phrase":"install software"},{"phrase":"install an app"},{"phrase":"install a system"}]', NULL, '/ɪnˈstɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insta/install__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 4, 'calculate', 'tính toán; tính', 'verb', '[{"en":"Can you calculate how much we spent on food this month?","vi":"Bạn có thể tính xem tháng này chúng ta đã tiêu bao nhiêu tiền ăn không?"},{"en":"The app calculates the distance you walk every day.","vi":"Ứng dụng tính quãng đường bạn đi bộ mỗi ngày."},{"en":"She carefully calculated the cost before booking the trip.","vi":"Cô ấy đã tính toán kỹ chi phí trước khi đặt chuyến đi."}]', '[{"phrase":"calculate the cost"},{"phrase":"calculate the distance"},{"phrase":"carefully calculate"}]', NULL, '/ˈkælkjuleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cal/calcu/calculate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 5, 'mouse', 'con chuột; chuột máy tính', 'noun', '[{"en":"My little sister screamed when she saw a mouse in the kitchen.","vi":"Em gái tôi hét lên khi thấy một con chuột trong bếp."},{"en":"Our cat caught two mice in the garden yesterday.","vi":"Hôm qua con mèo nhà tôi bắt được hai con chuột trong vườn."},{"en":"Click the right mouse button to open the menu.","vi":"Nhấp chuột phải để mở menu."}]', '[{"phrase":"computer mouse"},{"phrase":"mouse button"},{"phrase":"click the mouse"}]', 'số nhiều: mice', '/maʊs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mou/mouse/mouse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 6, 'mathematics', 'toán học', 'noun', '[{"en":"He studied mathematics at university and now teaches at a high school.","vi":"Anh ấy học toán ở đại học và giờ dạy ở một trường cấp ba."},{"en":"Mathematics was always my favorite subject at school.","vi":"Toán luôn là môn học yêu thích của tôi ở trường."},{"en":"You need basic mathematics to manage your money well.","vi":"Bạn cần kiến thức toán học cơ bản để quản lý tiền bạc tốt."}]', '[{"phrase":"study mathematics"},{"phrase":"basic mathematics"},{"phrase":"mathematics teacher"}]', 'không đếm được; viết tắt: math (Mỹ), maths (Anh)', '/ˌmæθəˈmætɪks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/mathe/mathematics__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 7, 'upper', 'phía trên; cao hơn', 'adjective', '[{"en":"Our apartment is on the upper floor, so it''s quite quiet.","vi":"Căn hộ của chúng tôi ở tầng trên nên khá yên tĩnh."},{"en":"He hurt his upper arm while playing basketball.","vi":"Anh ấy bị đau phần cánh tay trên khi chơi bóng rổ."},{"en":"Please write your name in the upper corner of the page.","vi":"Hãy viết tên bạn ở góc trên của trang giấy."}]', '[{"phrase":"upper floor"},{"phrase":"upper arm"},{"phrase":"upper body"},{"phrase":"upper class"}]', NULL, '/ˈʌpər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/upp/upper/upper__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 8, 'creation', 'sự tạo ra; tác phẩm', 'noun', '[{"en":"The new factory will lead to the creation of hundreds of jobs.","vi":"Nhà máy mới sẽ tạo ra hàng trăm việc làm."},{"en":"This cake is the chef''s latest creation.","vi":"Chiếc bánh này là tác phẩm mới nhất của đầu bếp."},{"en":"She has been involved in the creation of the website from the start.","vi":"Cô ấy đã tham gia xây dựng trang web ngay từ đầu."}]', '[{"phrase":"job creation"},{"phrase":"the creation of"},{"phrase":"latest creation"}]', NULL, '/kriˈeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/creation__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 9, 'occupy', 'chiếm; sử dụng; làm bận rộn', 'verb', '[{"en":"All the seats near the window were already occupied.","vi":"Tất cả chỗ ngồi gần cửa sổ đều đã có người ngồi."},{"en":"Our office occupies the second floor of the building.","vi":"Văn phòng của chúng tôi chiếm tầng hai của tòa nhà."},{"en":"I bring a few books to keep the kids occupied on long trips.","vi":"Tôi mang theo vài cuốn sách để bọn trẻ có việc làm trong những chuyến đi dài."}]', '[{"phrase":"occupy a seat"},{"phrase":"occupy a building"},{"phrase":"keep someone occupied"}]', NULL, '/ˈɑːkjupaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occup/occupy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 10, 'outline', 'dàn ý; nét chính; đường nét', 'noun', '[{"en":"Write a short outline before you start your essay.","vi":"Hãy viết một dàn ý ngắn trước khi bắt đầu bài luận."},{"en":"The manager gave us a brief outline of the new plan.","vi":"Người quản lý đã trình bày ngắn gọn những nét chính của kế hoạch mới."},{"en":"In the fog, we could only see the outline of the bridge.","vi":"Trong sương mù, chúng tôi chỉ nhìn thấy đường nét của cây cầu."}]', '[{"phrase":"brief outline"},{"phrase":"rough outline"},{"phrase":"the outline of"}]', NULL, '/ˈaʊtlaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outli/outline__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 11, 'sufficient', 'đủ', 'adjective', '[{"en":"We don''t have sufficient time to finish the project this week.","vi":"Chúng tôi không có đủ thời gian để hoàn thành dự án trong tuần này."},{"en":"Two hours of practice a day should be sufficient.","vi":"Mỗi ngày luyện tập hai tiếng là đủ."},{"en":"The hotel room was small but sufficient for a short stay.","vi":"Phòng khách sạn nhỏ nhưng đủ cho một kỳ nghỉ ngắn."}]', '[{"phrase":"sufficient time"},{"phrase":"sufficient money"},{"phrase":"sufficient evidence"}]', NULL, '/səˈfɪʃnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suf/suffi/sufficient__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 12, 'update', 'cập nhật; báo tin mới', 'verb', '[{"en":"Please update your phone to the latest version.","vi":"Vui lòng cập nhật điện thoại của bạn lên phiên bản mới nhất."},{"en":"I''ll update you when I hear back from the doctor.","vi":"Tôi sẽ báo tin cho bạn khi có hồi âm từ bác sĩ."},{"en":"The company updates its website almost every day.","vi":"Công ty cập nhật trang web gần như mỗi ngày."}]', '[{"phrase":"update software"},{"phrase":"update a website"},{"phrase":"keep someone updated"}]', NULL, '/ˌʌpˈdeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/upd/updat/update__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 13, 'luck', 'may mắn; vận may', 'noun', '[{"en":"Good luck with your big exam tomorrow morning!","vi":"Chúc bạn may mắn trong kỳ thi quan trọng sáng mai!"},{"en":"We had some bad luck with the weather on our holiday.","vi":"Chúng tôi gặp chút xui xẻo về thời tiết trong kỳ nghỉ."},{"en":"It was pure luck that I found my keys in the park.","vi":"Tôi tìm thấy chìa khóa trong công viên hoàn toàn là nhờ may mắn."}]', '[{"phrase":"good luck"},{"phrase":"bad luck"},{"phrase":"pure luck"},{"phrase":"wish someone luck"}]', 'không đếm được', '/lʌk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/luc/luck_/luck__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 14, 'preserve', 'giữ gìn; bảo tồn; bảo quản', 'verb', '[{"en":"The town has worked hard to preserve its old buildings.","vi":"Thị trấn đã nỗ lực rất nhiều để bảo tồn những tòa nhà cổ."},{"en":"Salt was used to preserve fish before people had fridges.","vi":"Muối được dùng để bảo quản cá trước khi người ta có tủ lạnh."},{"en":"It''s important to preserve our traditions for future generations.","vi":"Việc giữ gìn truyền thống cho các thế hệ tương lai là rất quan trọng."}]', '[{"phrase":"preserve the environment"},{"phrase":"preserve traditions"},{"phrase":"preserve food"}]', NULL, '/prɪˈzɜːrv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prese/preserve__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 15, 'split', 'chia; tách ra', 'verb', '[{"en":"Let''s split the bill between the four of us.","vi":"Hãy chia hóa đơn cho cả bốn người chúng ta."},{"en":"The teacher split the class into small groups.","vi":"Giáo viên chia lớp thành các nhóm nhỏ."},{"en":"He splits his time between work and caring for his mother.","vi":"Anh ấy chia thời gian giữa công việc và việc chăm sóc mẹ."}]', '[{"phrase":"split the bill"},{"phrase":"split into groups"},{"phrase":"split the cost"}]', 'split – split – split', '/splɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spl/split/split__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 16, 'swing', 'đung đưa; đu; xoay mạnh', 'verb', '[{"en":"The children were swinging on a rope by the river.","vi":"Bọn trẻ đang đu dây bên bờ sông."},{"en":"She sat on the edge of the table, swinging her legs.","vi":"Cô ấy ngồi ở mép bàn, đung đưa hai chân."},{"en":"The door swung open and a cold wind blew in.","vi":"Cánh cửa bật mở và một cơn gió lạnh thổi vào."}]', '[{"phrase":"swing open"},{"phrase":"swing back and forth"},{"phrase":"swing your arms"}]', 'swing – swung – swung', '/swɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swi/swing/swing__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 17, 'illness', 'bệnh; sự đau ốm', 'noun', '[{"en":"My grandfather recovered quickly from his illness.","vi":"Ông tôi đã hồi phục nhanh sau trận ốm."},{"en":"She missed two weeks of school because of illness.","vi":"Cô bé nghỉ học hai tuần vì bị ốm."},{"en":"Regular exercise can help protect you from serious illness.","vi":"Tập thể dục đều đặn có thể giúp bạn phòng tránh bệnh nặng."}]', '[{"phrase":"serious illness"},{"phrase":"long illness"},{"phrase":"recover from an illness"}]', NULL, '/ˈɪlnəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illne/illness__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 18, 'journalist', 'nhà báo', 'noun', '[{"en":"My cousin works as a journalist for a local newspaper.","vi":"Anh họ tôi làm nhà báo cho một tờ báo địa phương."},{"en":"Several journalists were waiting outside the hospital.","vi":"Vài nhà báo đang chờ bên ngoài bệnh viện."},{"en":"She dreamed of becoming a journalist and traveling the world.","vi":"Cô ấy mơ ước trở thành nhà báo và đi khắp thế giới."}]', '[{"phrase":"young journalist"},{"phrase":"local journalist"},{"phrase":"become a journalist"}]', NULL, '/ˈdʒɜːrnəlɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jou/journ/journalist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 19, 'sudden', 'đột ngột; bất ngờ', 'adjective', '[{"en":"The sudden noise woke the baby up.","vi":"Tiếng động đột ngột làm em bé thức giấc."},{"en":"There was a sudden change in the weather this afternoon.","vi":"Chiều nay thời tiết thay đổi đột ngột."},{"en":"All of a sudden, the lights in the whole house went out.","vi":"Đột nhiên đèn trong cả nhà tắt phụt."}]', '[{"phrase":"sudden change"},{"phrase":"sudden noise"},{"phrase":"all of a sudden"}]', 'all of a sudden = đột nhiên', '/ˈsʌdn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sud/sudde/sudden__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 20, 'advertisement', 'quảng cáo', 'noun', '[{"en":"I saw an advertisement for a cheap apartment near the station.","vi":"Tôi thấy một quảng cáo cho thuê căn hộ giá rẻ gần nhà ga."},{"en":"The company put an advertisement in the newspaper for new staff.","vi":"Công ty đăng quảng cáo trên báo để tuyển nhân viên mới."},{"en":"There are too many advertisements before this video starts.","vi":"Có quá nhiều quảng cáo trước khi video này bắt đầu."}]', '[{"phrase":"job advertisement"},{"phrase":"newspaper advertisement"},{"phrase":"place an advertisement"}]', 'viết tắt: ad (Mỹ), advert (Anh)', '/ˌædvərˈtaɪzmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/adver/advertisement__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 21, 'consistent', 'nhất quán; đều đặn; ổn định', 'adjective', '[{"en":"Parents need to be consistent when setting rules for children.","vi":"Cha mẹ cần nhất quán khi đặt ra quy tắc cho con cái."},{"en":"She has been a consistent player throughout the season.","vi":"Cô ấy là một cầu thủ thi đấu ổn định suốt mùa giải."},{"en":"Consistent practice is the key to learning a language.","vi":"Luyện tập đều đặn là chìa khóa để học một ngôn ngữ."}]', '[{"phrase":"consistent with"},{"phrase":"consistent quality"},{"phrase":"remain consistent"}]', 'consistent with sth = phù hợp với', '/kənˈsɪstənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsistent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 22, 'originally', 'ban đầu; lúc đầu; vốn', 'adverb', '[{"en":"The meeting was originally planned for Monday.","vi":"Cuộc họp ban đầu được lên kế hoạch vào thứ Hai."},{"en":"My family is originally from a small village in the north.","vi":"Gia đình tôi vốn gốc ở một ngôi làng nhỏ ở miền Bắc."},{"en":"This building was originally a school, but now it''s a hotel.","vi":"Tòa nhà này lúc đầu là trường học, nhưng giờ là khách sạn."}]', '[{"phrase":"originally planned"},{"phrase":"originally from"},{"phrase":"originally built"}]', NULL, '/əˈrɪdʒənəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ori/origi/originally__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 23, 'aside', 'sang một bên; để dành', 'adverb', '[{"en":"He stepped aside to let the old woman pass.","vi":"Anh ấy bước sang một bên để bà cụ đi qua."},{"en":"I try to put aside some money every month.","vi":"Tôi cố gắng để dành một ít tiền mỗi tháng."},{"en":"Let''s leave that problem aside for now and discuss the budget.","vi":"Tạm gác vấn đề đó sang một bên và bàn về ngân sách nhé."}]', '[{"phrase":"put aside"},{"phrase":"step aside"},{"phrase":"set aside"},{"phrase":"aside from"}]', 'aside from = ngoài ra; trừ', '/əˈsaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/asi/aside/aside__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 24, 'comfort', 'sự thoải mái; sự an ủi', 'noun', '[{"en":"These shoes are designed for comfort, not style.","vi":"Đôi giày này được thiết kế cho sự thoải mái, không phải cho kiểu dáng."},{"en":"Now you can shop from the comfort of your own home.","vi":"Giờ đây bạn có thể mua sắm thoải mái ngay tại nhà mình."},{"en":"Her friends were a great comfort to her after the accident.","vi":"Bạn bè là nguồn an ủi lớn đối với cô ấy sau tai nạn."}]', '[{"phrase":"in comfort"},{"phrase":"great comfort"},{"phrase":"the comfort of your own home"}]', NULL, '/ˈkʌmfərt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comfo/comfort__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 25, 'secondly', 'thứ hai là', 'adverb', '[{"en":"Firstly, the room is too small, and secondly, it''s too expensive.","vi":"Thứ nhất, căn phòng quá nhỏ, và thứ hai, nó quá đắt."},{"en":"Secondly, we need to find a cheaper place for the party.","vi":"Thứ hai, chúng ta cần tìm một chỗ rẻ hơn để tổ chức tiệc."},{"en":"I chose this job firstly because it''s close to home and secondly because it pays well.","vi":"Tôi chọn công việc này, thứ nhất vì nó gần nhà và thứ hai vì lương tốt."}]', '[{"phrase":"and secondly"},{"phrase":"firstly, secondly"}]', NULL, '/ˈsekəndli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secon/secondly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 26, 'severe', 'nghiêm trọng; dữ dội; khắc nghiệt', 'adjective', '[{"en":"He was taken to hospital with severe pain in his stomach.","vi":"Anh ấy được đưa vào viện vì đau bụng dữ dội."},{"en":"The severe weather closed many roads in the mountains.","vi":"Thời tiết khắc nghiệt đã khiến nhiều con đường trên núi bị đóng."},{"en":"The city is facing a severe shortage of clean water.","vi":"Thành phố đang đối mặt với tình trạng thiếu nước sạch nghiêm trọng."}]', '[{"phrase":"severe pain"},{"phrase":"severe weather"},{"phrase":"severe shortage"},{"phrase":"severe damage"}]', NULL, '/sɪˈvɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sev/sever/severe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 27, 'gene', 'gen', 'noun', '[{"en":"Scientists have found a gene linked to heart disease.","vi":"Các nhà khoa học đã tìm ra một gen liên quan đến bệnh tim."},{"en":"Your eye color depends on the genes you get from your parents.","vi":"Màu mắt của bạn phụ thuộc vào gen bạn thừa hưởng từ cha mẹ."},{"en":"Some people have genes that help them live longer.","vi":"Một số người có gen giúp họ sống lâu hơn."}]', '[{"phrase":"gene for"},{"phrase":"human gene"},{"phrase":"carry a gene"}]', NULL, '/dʒiːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gene_/gene_1_us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 28, 'prospect', 'triển vọng; khả năng; viễn cảnh', 'noun', '[{"en":"There is little prospect of the rain stopping today.","vi":"Hầu như không có khả năng hôm nay trời tạnh mưa."},{"en":"Learning English can improve your job prospects.","vi":"Học tiếng Anh có thể cải thiện triển vọng việc làm của bạn."},{"en":"The prospect of moving abroad made her a little nervous.","vi":"Viễn cảnh chuyển ra nước ngoài khiến cô ấy hơi lo lắng."}]', '[{"phrase":"job prospects"},{"phrase":"career prospects"},{"phrase":"the prospect of"}]', NULL, '/ˈprɑːspekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prosp/prospect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 29, 'snow', 'tuyết', 'noun', '[{"en":"The children played in the snow all afternoon.","vi":"Bọn trẻ chơi đùa trên tuyết suốt cả buổi chiều."},{"en":"We had so much snow last night that the school closed.","vi":"Đêm qua tuyết rơi nhiều đến mức trường phải đóng cửa."},{"en":"I''ve never seen snow because it''s too hot in my hometown.","vi":"Tôi chưa bao giờ thấy tuyết vì quê tôi quá nóng."}]', '[{"phrase":"heavy snow"},{"phrase":"in the snow"},{"phrase":"covered in snow"}]', 'không đếm được', '/snəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sno/snow_/snow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-15', 30, 'plot', 'cốt truyện; mảnh đất', 'noun', '[{"en":"The movie has a simple plot but great acting.","vi":"Bộ phim có cốt truyện đơn giản nhưng diễn xuất rất hay."},{"en":"I didn''t understand the plot of the book at first.","vi":"Lúc đầu tôi không hiểu cốt truyện của cuốn sách."},{"en":"My parents bought a small plot of land to grow vegetables.","vi":"Bố mẹ tôi đã mua một mảnh đất nhỏ để trồng rau."}]', '[{"phrase":"the plot of"},{"phrase":"main plot"},{"phrase":"plot of land"}]', NULL, '/plɑːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/plo/plot_/plot__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-16', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 16', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 16);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 1, 'neck', 'cổ', 'noun', '[{"en":"I slept in a strange position and now my neck hurts.","vi":"Tôi ngủ sai tư thế nên bây giờ bị đau cổ."},{"en":"She wore a thin gold chain around her neck.","vi":"Cô ấy đeo một sợi dây chuyền vàng mảnh quanh cổ."},{"en":"Giraffes use their long necks to reach leaves high in the trees.","vi":"Hươu cao cổ dùng chiếc cổ dài để với tới lá trên cao."}]', '[{"phrase":"long neck"},{"phrase":"stiff neck"},{"phrase":"around your neck"},{"phrase":"neck pain"}]', NULL, '/nek/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nec/neck_/neck__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 2, 'criteria', 'tiêu chí; tiêu chuẩn', 'noun', '[{"en":"What criteria do you use when choosing a new employee?","vi":"Bạn dùng những tiêu chí nào khi chọn một nhân viên mới?"},{"en":"Only three students met all the criteria for the scholarship.","vi":"Chỉ có ba học sinh đáp ứng tất cả tiêu chuẩn để nhận học bổng."},{"en":"The judges explained the criteria before the competition started.","vi":"Ban giám khảo giải thích các tiêu chí trước khi cuộc thi bắt đầu."}]', '[{"phrase":"meet the criteria"},{"phrase":"selection criteria"},{"phrase":"strict criteria"},{"phrase":"criteria for"}]', 'số nhiều của criterion', '/kraɪˈtɪriːə/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 3, 'primarily', 'chủ yếu; trước hết', 'adverb', '[{"en":"This app is designed primarily for young children.","vi":"Ứng dụng này được thiết kế chủ yếu cho trẻ nhỏ."},{"en":"Our customers are primarily small businesses in the city.","vi":"Khách hàng của chúng tôi chủ yếu là các doanh nghiệp nhỏ trong thành phố."},{"en":"He moved abroad primarily to be closer to his daughter.","vi":"Anh ấy chuyển ra nước ngoài trước hết là để được gần con gái hơn."}]', '[{"phrase":"primarily responsible"},{"phrase":"primarily because"},{"phrase":"primarily designed for"},{"phrase":"primarily used"}]', NULL, '/praɪˈmerəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prima/primarily__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 4, 'integrate', 'hòa nhập; tích hợp', 'verb', '[{"en":"It took the new students a few weeks to integrate into the class.","vi":"Các học sinh mới mất vài tuần để hòa nhập với lớp."},{"en":"The new camera is fully integrated into the phone''s software.","vi":"Máy ảnh mới được tích hợp hoàn toàn vào phần mềm của điện thoại."},{"en":"We need to integrate these two systems before the end of the year.","vi":"Chúng ta cần tích hợp hai hệ thống này trước cuối năm."}]', '[{"phrase":"integrate into"},{"phrase":"integrate with"},{"phrase":"fully integrated"}]', 'integrate into/with', '/ˈɪntɪɡreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/integ/integrate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 5, 'criticism', 'sự chỉ trích; lời phê bình', 'noun', '[{"en":"The new rules have received a lot of criticism from parents.","vi":"Các quy định mới đã nhận nhiều chỉ trích từ phụ huynh."},{"en":"She is good at accepting criticism and learning from it.","vi":"Cô ấy giỏi tiếp nhận lời phê bình và học hỏi từ đó."},{"en":"My teacher always gives helpful criticism of my essays.","vi":"Thầy giáo tôi luôn đưa ra những lời phê bình hữu ích về bài luận của tôi."}]', '[{"phrase":"receive criticism"},{"phrase":"accept criticism"},{"phrase":"constructive criticism"},{"phrase":"criticism of"}]', NULL, '/ˈkrɪtɪsɪzəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/criti/criticism__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 6, 'convention', 'hội nghị; quy ước, tục lệ', 'noun', '[{"en":"Thousands of teachers attended the national convention in the capital.","vi":"Hàng nghìn giáo viên đã tham dự hội nghị toàn quốc ở thủ đô."},{"en":"By convention, the bride''s family pays for the wedding.","vi":"Theo tục lệ, nhà gái chi trả cho đám cưới."},{"en":"In many countries, it is a convention to shake hands when meeting.","vi":"Ở nhiều nước, bắt tay khi gặp nhau là một quy ước."}]', '[{"phrase":"annual convention"},{"phrase":"national convention"},{"phrase":"by convention"},{"phrase":"social convention"}]', NULL, '/kənˈvenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvention__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 7, 'bet', 'cá cược; dám chắc', 'verb', '[{"en":"He bet twenty dollars that his team would win.","vi":"Anh ấy cược hai mươi đô la rằng đội của mình sẽ thắng."},{"en":"I bet you''re tired after such a long flight.","vi":"Tôi dám chắc bạn mệt sau một chuyến bay dài như vậy."},{"en":"My uncle never bets money on football games.","vi":"Chú tôi không bao giờ cá tiền vào các trận bóng đá."}]', '[{"phrase":"bet money"},{"phrase":"bet on"},{"phrase":"I bet"},{"phrase":"you bet"}]', 'bet – bet – bet', '/bet/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bet/bet__/bet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 8, 'retain', 'giữ lại; duy trì', 'verb', '[{"en":"The company offers good pay to retain its best workers.","vi":"Công ty trả lương tốt để giữ chân những nhân viên giỏi nhất."},{"en":"Please retain your receipt in case you need to return the item.","vi":"Vui lòng giữ lại hóa đơn phòng khi bạn cần trả hàng."},{"en":"The old town has retained much of its traditional charm.","vi":"Khu phố cổ vẫn duy trì được phần lớn nét duyên truyền thống."}]', '[{"phrase":"retain staff"},{"phrase":"retain control"},{"phrase":"retain information"},{"phrase":"retain heat"}]', NULL, '/rɪˈteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retai/retain__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 9, 'sequence', 'trình tự; chuỗi', 'noun', '[{"en":"Put these pictures in the correct sequence to tell the story.","vi":"Hãy xếp những bức tranh này theo đúng trình tự để kể câu chuyện."},{"en":"The opening sequence of the film was really exciting.","vi":"Chuỗi cảnh mở đầu của bộ phim thật sự hấp dẫn."},{"en":"A strange sequence of events led to their first meeting.","vi":"Một chuỗi sự việc kỳ lạ đã dẫn đến lần gặp đầu tiên của họ."}]', '[{"phrase":"sequence of events"},{"phrase":"in sequence"},{"phrase":"correct sequence"},{"phrase":"opening sequence"}]', NULL, '/ˈsiːkwəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/seq/seque/sequence__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 10, 'plain', 'đơn giản, trơn; rõ ràng', 'adjective', '[{"en":"She prefers plain white shirts to colorful ones.","vi":"Cô ấy thích áo sơ mi trắng trơn hơn áo sặc sỡ."},{"en":"It was plain that he didn''t want to talk about it.","vi":"Rõ ràng là anh ấy không muốn nói về chuyện đó."},{"en":"Could you explain the contract in plain English, please?","vi":"Bạn có thể giải thích hợp đồng bằng tiếng Anh dễ hiểu được không?"}]', '[{"phrase":"plain English"},{"phrase":"plain white"},{"phrase":"make it plain"},{"phrase":"plain yogurt"}]', NULL, '/pleɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plain/plain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 11, 'volunteer', 'tình nguyện viên', 'noun', '[{"en":"The festival is run entirely by volunteers from the town.","vi":"Lễ hội hoàn toàn do các tình nguyện viên trong thị trấn tổ chức."},{"en":"My sister works as a volunteer at the animal shelter.","vi":"Chị tôi làm tình nguyện viên ở trại cứu hộ động vật."},{"en":"We still need a few more volunteers to clean the beach.","vi":"Chúng tôi vẫn cần thêm vài tình nguyện viên để dọn dẹp bãi biển."}]', '[{"phrase":"volunteer work"},{"phrase":"work as a volunteer"},{"phrase":"need volunteers"}]', 'cũng là động từ: volunteer to do sth (tình nguyện làm gì)', '/ˌvɑːlənˈtɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volun/volunteer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 12, 'rural', '(thuộc) nông thôn', 'adjective', '[{"en":"My grandparents still live in a small rural village.","vi":"Ông bà tôi vẫn sống ở một ngôi làng nhỏ vùng nông thôn."},{"en":"Many young people leave rural areas to find work in cities.","vi":"Nhiều người trẻ rời vùng nông thôn để tìm việc ở thành phố."},{"en":"Life in rural communities is often quieter and slower.","vi":"Cuộc sống ở các cộng đồng nông thôn thường yên tĩnh và chậm rãi hơn."}]', '[{"phrase":"rural area"},{"phrase":"rural village"},{"phrase":"rural community"},{"phrase":"rural life"}]', 'rural ≠ urban (thành thị)', '/ˈrʊrəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rur/rural/rural__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 13, 'calm', 'bình tĩnh; yên tĩnh, êm', 'adjective', '[{"en":"Try to stay calm and answer the questions slowly.","vi":"Hãy cố giữ bình tĩnh và trả lời các câu hỏi thật chậm rãi."},{"en":"The sea was calm, so we went out in a small boat.","vi":"Biển êm nên chúng tôi ra khơi trên một chiếc thuyền nhỏ."},{"en":"She spoke in a calm voice even though she was angry.","vi":"Cô ấy nói bằng giọng bình tĩnh dù đang tức giận."}]', '[{"phrase":"stay calm"},{"phrase":"keep calm"},{"phrase":"calm voice"},{"phrase":"calm sea"}]', NULL, '/kɑːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cal/calm_/calm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 14, 'abandon', 'bỏ rơi; từ bỏ', 'verb', '[{"en":"Someone abandoned a tiny puppy outside our building last night.","vi":"Tối qua ai đó đã bỏ rơi một chú cún nhỏ trước tòa nhà chúng tôi."},{"en":"They had to abandon the game because of heavy rain.","vi":"Họ phải bỏ dở trận đấu vì mưa lớn."},{"en":"He never abandoned his dream of becoming a doctor.","vi":"Anh ấy chưa bao giờ từ bỏ ước mơ trở thành bác sĩ."}]', '[{"phrase":"abandon a plan"},{"phrase":"abandon hope"},{"phrase":"abandoned car"},{"phrase":"abandon a project"}]', NULL, '/əˈbændən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aba/aband/abandon__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 15, 'examination', 'kỳ thi; sự kiểm tra, khám', 'noun', '[{"en":"All students must pass the final examination to graduate.","vi":"Tất cả học sinh phải vượt qua kỳ thi cuối cùng để tốt nghiệp."},{"en":"The doctor did a quick examination of my injured knee.","vi":"Bác sĩ khám nhanh đầu gối bị thương của tôi."},{"en":"After careful examination, the police found no evidence.","vi":"Sau khi kiểm tra kỹ lưỡng, cảnh sát không tìm thấy bằng chứng nào."}]', '[{"phrase":"pass an examination"},{"phrase":"medical examination"},{"phrase":"careful examination"},{"phrase":"final examination"}]', 'thường nói tắt: exam', '/ɪɡˌzæmɪˈneɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exami/examination__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 16, 'silence', 'sự im lặng', 'noun', '[{"en":"There was a long silence after she asked the question.","vi":"Có một khoảng im lặng dài sau khi cô ấy đặt câu hỏi."},{"en":"We ate our dinner in silence, too tired to talk.","vi":"Chúng tôi ăn tối trong im lặng, mệt đến mức không muốn nói."},{"en":"The sudden noise broke the silence of the library.","vi":"Tiếng động bất ngờ đã phá vỡ sự im lặng của thư viện."}]', '[{"phrase":"in silence"},{"phrase":"break the silence"},{"phrase":"long silence"},{"phrase":"complete silence"}]', NULL, '/ˈsaɪləns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sil/silen/silence__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 17, 'rapidly', 'nhanh chóng', 'adverb', '[{"en":"The city has grown rapidly over the last ten years.","vi":"Thành phố đã phát triển nhanh chóng trong mười năm qua."},{"en":"Prices are rising rapidly, so we should buy now.","vi":"Giá cả đang tăng nhanh chóng nên chúng ta nên mua ngay."},{"en":"Her English improved rapidly after she moved abroad.","vi":"Tiếng Anh của cô ấy tiến bộ nhanh chóng sau khi chuyển ra nước ngoài."}]', '[{"phrase":"grow rapidly"},{"phrase":"change rapidly"},{"phrase":"rapidly increasing"},{"phrase":"move rapidly"}]', NULL, '/ˈræpɪdli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rap/rapid/rapidly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 18, 'efficient', 'hiệu quả; làm việc năng suất', 'adjective', '[{"en":"Trains are a fast and efficient way to travel.","vi":"Tàu hỏa là cách di chuyển nhanh và hiệu quả."},{"en":"Our new manager is very efficient and well organized.","vi":"Quản lý mới của chúng tôi làm việc rất năng suất và ngăn nắp."},{"en":"This fridge is more energy efficient than our old one.","vi":"Chiếc tủ lạnh này tiết kiệm năng lượng hơn chiếc cũ của chúng tôi."}]', '[{"phrase":"energy efficient"},{"phrase":"highly efficient"},{"phrase":"efficient way"},{"phrase":"more efficient"}]', 'efficient (ít lãng phí) ≠ effective (đạt kết quả)', '/ɪˈfɪʃnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effic/efficient__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 19, 'revolution', 'cuộc cách mạng', 'noun', '[{"en":"The internet started a revolution in the way we communicate.","vi":"Internet đã mở ra một cuộc cách mạng trong cách chúng ta giao tiếp."},{"en":"We learned about the Industrial Revolution in history class.","vi":"Chúng tôi đã học về Cách mạng Công nghiệp trong giờ lịch sử."},{"en":"Smartphones brought about a revolution in photography.","vi":"Điện thoại thông minh đã tạo ra một cuộc cách mạng trong nhiếp ảnh."}]', '[{"phrase":"industrial revolution"},{"phrase":"technological revolution"},{"phrase":"revolution in"},{"phrase":"digital revolution"}]', NULL, '/ˌrevəˈluːʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revol/revolution__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 20, 'delight', 'niềm vui sướng; điều thú vị', 'noun', '[{"en":"The children shouted with delight when they saw the snow.","vi":"Bọn trẻ reo lên vui sướng khi nhìn thấy tuyết."},{"en":"To my delight, my old friend came to visit me.","vi":"Tôi rất vui mừng khi người bạn cũ đến thăm mình."},{"en":"This little café is a real delight for coffee lovers.","vi":"Quán cà phê nhỏ này thật sự là một điều thú vị với người mê cà phê."}]', '[{"phrase":"with delight"},{"phrase":"to my delight"},{"phrase":"take delight in"},{"phrase":"real delight"}]', NULL, '/dɪˈlaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/del/delig/delight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 21, 'spell', 'đánh vần; viết đúng chính tả', 'verb', '[{"en":"Could you spell your last name for me, please?","vi":"Bạn có thể đánh vần họ của bạn cho tôi được không?"},{"en":"I always forget how to spell this word correctly.","vi":"Tôi luôn quên cách viết đúng chính tả của từ này."},{"en":"My little brother can already spell his own name.","vi":"Em trai nhỏ của tôi đã biết đánh vần tên của mình."}]', '[{"phrase":"spell your name"},{"phrase":"spell correctly"},{"phrase":"how to spell"}]', 'Mỹ: spelled · Anh: spelt', '/spel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/spell/spell__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 22, 'premise', 'tiền đề; ý tưởng cơ sở', 'noun', '[{"en":"The whole plan is based on a false premise.","vi":"Toàn bộ kế hoạch dựa trên một tiền đề sai."},{"en":"The basic premise of the movie is simple but clever.","vi":"Ý tưởng cơ sở của bộ phim đơn giản nhưng thông minh."},{"en":"We started from the premise that everyone wants to learn.","vi":"Chúng tôi bắt đầu từ tiền đề rằng ai cũng muốn học."}]', '[{"phrase":"basic premise"},{"phrase":"false premise"},{"phrase":"based on the premise"},{"phrase":"premise of"}]', 'premises (số nhiều) = khuôn viên, cơ sở (nhà, đất)', '/ˈpremɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/premi/premise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 23, 'lean', 'dựa, tựa; nghiêng người', 'verb', '[{"en":"He leaned against the wall and waited for the bus.","vi":"Anh ấy tựa vào tường và chờ xe buýt."},{"en":"Don''t lean out of the window while the train is moving.","vi":"Đừng nhoài người ra ngoài cửa sổ khi tàu đang chạy."},{"en":"She leaned forward to hear what the teacher was saying.","vi":"Cô ấy nghiêng người về phía trước để nghe thầy giáo nói gì."}]', '[{"phrase":"lean against"},{"phrase":"lean forward"},{"phrase":"lean back"},{"phrase":"lean on"}]', 'Mỹ: leaned · Anh: leaned/leant', '/liːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/lean_/lean__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 24, 'dramatic', 'đột ngột, mạnh mẽ; kịch tính', 'adjective', '[{"en":"There has been a dramatic increase in house prices this year.","vi":"Năm nay giá nhà đã tăng mạnh."},{"en":"The game had a dramatic ending in the final minute.","vi":"Trận đấu có một kết thúc đầy kịch tính ở phút cuối cùng."},{"en":"Moving to a new country was a dramatic change for our family.","vi":"Chuyển đến một đất nước mới là một thay đổi lớn đối với gia đình tôi."}]', '[{"phrase":"dramatic change"},{"phrase":"dramatic increase"},{"phrase":"dramatic effect"},{"phrase":"dramatic ending"}]', NULL, '/drəˈmætɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drama/dramatic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 25, 'differ', 'khác nhau; bất đồng', 'verb', '[{"en":"Prices differ a lot from one shop to another.","vi":"Giá cả khác nhau rất nhiều giữa các cửa hàng."},{"en":"How does this phone differ from the older model?","vi":"Chiếc điện thoại này khác mẫu cũ ở điểm nào?"},{"en":"My parents often differ on how to spend money.","vi":"Bố mẹ tôi thường bất đồng về cách tiêu tiền."}]', '[{"phrase":"differ from"},{"phrase":"differ greatly"},{"phrase":"differ in"},{"phrase":"opinions differ"}]', 'differ from (khác với)', '/ˈdɪfər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/differ__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 26, 'grateful', 'biết ơn', 'adjective', '[{"en":"I''m really grateful for all your help this week.","vi":"Tôi thật sự biết ơn tất cả sự giúp đỡ của bạn tuần này."},{"en":"We would be grateful if you could reply soon.","vi":"Chúng tôi sẽ rất biết ơn nếu bạn có thể sớm trả lời."},{"en":"She was grateful to her teacher for believing in her.","vi":"Cô ấy biết ơn thầy giáo vì đã tin tưởng mình."}]', '[{"phrase":"grateful for"},{"phrase":"grateful to"},{"phrase":"deeply grateful"},{"phrase":"would be grateful"}]', 'grateful to sb for sth', '/ˈɡreɪtfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grate/grateful__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 27, 'protein', 'chất đạm, protein', 'noun', '[{"en":"Eggs and beans are cheap sources of protein.","vi":"Trứng và đậu là những nguồn chất đạm rẻ tiền."},{"en":"Athletes often need more protein than other people.","vi":"Vận động viên thường cần nhiều chất đạm hơn người khác."},{"en":"My doctor told me to eat more protein and less sugar.","vi":"Bác sĩ bảo tôi ăn nhiều chất đạm hơn và ít đường hơn."}]', '[{"phrase":"source of protein"},{"phrase":"high in protein"},{"phrase":"protein intake"}]', NULL, '/ˈprəʊtiːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prote/protein__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 28, 'bike', 'xe đạp', 'noun', '[{"en":"I ride my bike to school every morning.","vi":"Sáng nào tôi cũng đạp xe đến trường."},{"en":"Someone stole my bike while I was in the store.","vi":"Ai đó đã lấy trộm xe đạp của tôi khi tôi đang ở trong cửa hàng."},{"en":"Let''s go for a bike ride along the river this afternoon.","vi":"Chiều nay mình đi đạp xe dọc bờ sông nhé."}]', '[{"phrase":"ride a bike"},{"phrase":"bike ride"},{"phrase":"by bike"},{"phrase":"bike lane"}]', 'trong văn nói, bike cũng có thể chỉ xe máy', '/baɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bik/bike_/bike__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 29, 'distribute', 'phân phát; phân phối', 'verb', '[{"en":"Volunteers distributed food and water to the families.","vi":"Các tình nguyện viên đã phân phát thức ăn và nước uống cho các gia đình."},{"en":"The teacher distributed the test papers to the class.","vi":"Giáo viên phát bài kiểm tra cho cả lớp."},{"en":"This company distributes its products to shops across the country.","vi":"Công ty này phân phối sản phẩm đến các cửa hàng trên cả nước."}]', '[{"phrase":"distribute food"},{"phrase":"widely distributed"},{"phrase":"distribute to"},{"phrase":"distribute products"}]', NULL, '/dɪˈstrɪbjuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/distr/distribute__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-16', 30, 'intellectual', '(thuộc) trí tuệ', 'adjective', '[{"en":"Reading and puzzles are good for a child''s intellectual development.","vi":"Đọc sách và giải đố tốt cho sự phát triển trí tuệ của trẻ."},{"en":"The course was an intellectual challenge even for the best students.","vi":"Khóa học là một thử thách trí tuệ ngay cả với những sinh viên giỏi nhất."},{"en":"They enjoy intellectual conversations about books, art and history.","vi":"Họ thích những cuộc trò chuyện mang tính trí tuệ về sách, nghệ thuật và lịch sử."}]', '[{"phrase":"intellectual development"},{"phrase":"intellectual property"},{"phrase":"intellectual ability"},{"phrase":"intellectual challenge"}]', NULL, '/ˌɪntəˈlektʃuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intel/intellectual__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-17', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 17', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 17);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 1, 'derive', 'bắt nguồn từ; có được, lấy được (từ)', 'verb', '[{"en":"Many English words are derived from Latin or Greek.","vi":"Nhiều từ tiếng Anh bắt nguồn từ tiếng Latin hoặc tiếng Hy Lạp."},{"en":"She derives great pleasure from working in her garden.","vi":"Cô ấy có được niềm vui lớn từ việc làm vườn."},{"en":"This medicine is derived from a plant that grows in the rainforest.","vi":"Loại thuốc này được chiết xuất từ một loài cây mọc trong rừng mưa nhiệt đới."}]', '[{"phrase":"derive from"},{"phrase":"be derived from"},{"phrase":"derive pleasure from"}]', 'derive from: bắt nguồn từ', '/dɪˈraɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/der/deriv/derive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 2, 'crucial', 'rất quan trọng; then chốt', 'adjective', '[{"en":"Getting enough sleep is crucial for your health.","vi":"Ngủ đủ giấc rất quan trọng đối với sức khỏe của bạn."},{"en":"The next few days will be crucial for the team.","vi":"Vài ngày tới sẽ mang tính then chốt đối với đội."},{"en":"She played a crucial role in the success of the project.","vi":"Cô ấy đóng vai trò then chốt trong thành công của dự án."}]', '[{"phrase":"crucial role"},{"phrase":"crucial for"},{"phrase":"absolutely crucial"}]', NULL, '/ˈkruːʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cru/cruci/crucial__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 3, 'unemployment', 'sự thất nghiệp; tình trạng thất nghiệp', 'noun', '[{"en":"The unemployment rate has risen sharply in the past year.","vi":"Tỷ lệ thất nghiệp đã tăng mạnh trong năm qua."},{"en":"Many young people in the town struggle with unemployment.","vi":"Nhiều người trẻ trong thị trấn phải vật lộn với cảnh thất nghiệp."},{"en":"After losing his job, he received unemployment benefits for six months.","vi":"Sau khi mất việc, anh ấy nhận trợ cấp thất nghiệp trong sáu tháng."}]', '[{"phrase":"unemployment rate"},{"phrase":"high unemployment"},{"phrase":"unemployment benefits"},{"phrase":"youth unemployment"}]', 'không đếm được', '/ˌʌnɪmˈplɔɪmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/une/unemp/unemployment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 4, 'wheel', 'bánh xe; vô lăng', 'noun', '[{"en":"Can you help me put the front wheel back on my bike?","vi":"Bạn giúp tôi lắp lại bánh trước vào xe đạp được không?"},{"en":"One of the wheels on my suitcase broke at the airport.","vi":"Vali của tôi bị gãy một bánh xe ở sân bay."},{"en":"Keep both hands on the wheel when you drive.","vi":"Hãy giữ cả hai tay trên vô lăng khi lái xe."}]', '[{"phrase":"front wheel"},{"phrase":"back wheel"},{"phrase":"steering wheel"},{"phrase":"behind the wheel"}]', NULL, '/wiːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/wheel/wheel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 5, 'crop', 'cây trồng; vụ mùa', 'noun', '[{"en":"Rice is the main crop in this part of the country.","vi":"Lúa là cây trồng chính ở vùng này của đất nước."},{"en":"Farmers are worried that the dry weather will damage their crops.","vi":"Nông dân lo rằng thời tiết khô hạn sẽ gây hại cho cây trồng của họ."},{"en":"We had a good crop of apples this year.","vi":"Năm nay chúng tôi được mùa táo."}]', '[{"phrase":"grow crops"},{"phrase":"main crop"},{"phrase":"good crop"},{"phrase":"crop failure"}]', NULL, '/krɑːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cro/crop_/crop__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 6, 'minority', 'thiểu số; nhóm thiểu số', 'noun', '[{"en":"Only a minority of students chose to study abroad.","vi":"Chỉ một số ít sinh viên chọn đi du học."},{"en":"People who cycle to work are still in the minority here.","vi":"Ở đây, những người đạp xe đi làm vẫn là thiểu số."},{"en":"The school offers extra support for children from ethnic minorities.","vi":"Trường có hỗ trợ thêm cho trẻ em thuộc các dân tộc thiểu số."}]', '[{"phrase":"a minority of"},{"phrase":"in the minority"},{"phrase":"ethnic minority"},{"phrase":"small minority"}]', NULL, '/maɪˈnɔːrəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minor/minority__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 7, 'origin', 'nguồn gốc; xuất xứ', 'noun', '[{"en":"Nobody knows the true origin of this old song.","vi":"Không ai biết nguồn gốc thật sự của bài hát cổ này."},{"en":"The country of origin is printed on the label.","vi":"Nước xuất xứ được in trên nhãn."},{"en":"The festival has its origins in an ancient farming tradition.","vi":"Lễ hội này có nguồn gốc từ một truyền thống nông nghiệp cổ xưa."}]', '[{"phrase":"country of origin"},{"phrase":"have its origins in"},{"phrase":"the origin of"}]', NULL, '/ˈɔːrɪdʒɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ori/origi/origin__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 8, 'interpretation', 'cách hiểu, sự giải thích; cách thể hiện', 'noun', '[{"en":"Each student gave a different interpretation of the poem.","vi":"Mỗi học sinh đưa ra một cách hiểu khác nhau về bài thơ."},{"en":"The rules are clear and leave little room for interpretation.","vi":"Các quy định rất rõ ràng và hầu như không có chỗ cho cách hiểu khác."},{"en":"I loved her fresh interpretation of this famous piano piece.","vi":"Tôi rất thích cách thể hiện mới mẻ của cô ấy với bản nhạc piano nổi tiếng này."}]', '[{"phrase":"interpretation of"},{"phrase":"different interpretation"},{"phrase":"open to interpretation"},{"phrase":"room for interpretation"}]', NULL, '/ɪnˌtɜːrprəˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interpretation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 9, 'gentleman', 'quý ông; người đàn ông lịch thiệp', 'noun', '[{"en":"Could you show this gentleman to his table, please?","vi":"Bạn vui lòng dẫn quý ông này đến bàn của ông ấy nhé?"},{"en":"Good evening, ladies and gentlemen, and welcome to the show.","vi":"Xin chào quý vị, chào mừng quý vị đến với chương trình."},{"en":"My grandfather was a true gentleman who was kind to everyone.","vi":"Ông tôi là một quý ông thực thụ, luôn tử tế với mọi người."}]', '[{"phrase":"ladies and gentlemen"},{"phrase":"true gentleman"},{"phrase":"old gentleman"}]', 'số nhiều: gentlemen', '/ˈdʒentlmən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gentl/gentleman__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 10, 'drama', 'kịch, sân khấu; phim truyền hình; chuyện lùm xùm', 'noun', '[{"en":"She studied drama at college and now works in theater.","vi":"Cô ấy học ngành kịch ở đại học và giờ làm việc trong lĩnh vực sân khấu."},{"en":"We watched a new crime drama on TV last night.","vi":"Tối qua chúng tôi xem một bộ phim truyền hình hình sự mới."},{"en":"I just want a quiet weekend without any family drama.","vi":"Tôi chỉ muốn một cuối tuần yên tĩnh, không có chuyện lùm xùm gì trong gia đình."}]', '[{"phrase":"study drama"},{"phrase":"TV drama"},{"phrase":"crime drama"},{"phrase":"drama school"}]', NULL, '/ˈdrɑːmə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drama/drama__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 11, 'landscape', 'phong cảnh; cảnh quan', 'noun', '[{"en":"The landscape around the lake is beautiful in autumn.","vi":"Phong cảnh quanh hồ rất đẹp vào mùa thu."},{"en":"We drove for hours through a flat, empty landscape.","vi":"Chúng tôi lái xe hàng giờ qua một vùng cảnh quan bằng phẳng và trống trải."},{"en":"He loves painting landscapes more than people.","vi":"Anh ấy thích vẽ phong cảnh hơn là vẽ người."}]', '[{"phrase":"beautiful landscape"},{"phrase":"rural landscape"},{"phrase":"landscape painting"}]', NULL, '/ˈlændskeɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lan/lands/landscape__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 12, 'educate', 'giáo dục; cho đi học; nâng cao hiểu biết', 'verb', '[{"en":"Both of their children were educated at local schools.","vi":"Cả hai người con của họ đều được học ở các trường địa phương."},{"en":"The campaign aims to educate people about healthy eating.","vi":"Chiến dịch nhằm nâng cao hiểu biết của mọi người về ăn uống lành mạnh."},{"en":"Parents play a big part in educating their children.","vi":"Cha mẹ đóng vai trò lớn trong việc giáo dục con cái."}]', '[{"phrase":"educate people about"},{"phrase":"educate the public"},{"phrase":"well educated"}]', NULL, '/ˈedʒukeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edu/educa/educate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 13, 'toy', 'đồ chơi', 'noun', '[{"en":"Please put your toys away before dinner.","vi":"Con hãy cất đồ chơi đi trước bữa tối nhé."},{"en":"He bought his son a toy car for his birthday.","vi":"Anh ấy mua cho con trai một chiếc ô tô đồ chơi nhân dịp sinh nhật."},{"en":"The dog loves chewing on its old rubber toy.","vi":"Con chó thích gặm món đồ chơi cao su cũ của nó."}]', '[{"phrase":"toy car"},{"phrase":"play with toys"},{"phrase":"toy store"}]', NULL, '/tɔɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/toy/toy__/toy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 14, 'fault', 'lỗi (trách nhiệm); khuyết điểm; chỗ hỏng', 'noun', '[{"en":"It''s not your fault that the train was late.","vi":"Tàu đến muộn đâu phải lỗi của bạn."},{"en":"He has his faults, but he''s a loyal friend.","vi":"Anh ấy có những khuyết điểm, nhưng là một người bạn trung thành."},{"en":"The engineers found a fault in the electrical system.","vi":"Các kỹ sư đã phát hiện một chỗ hỏng trong hệ thống điện."}]', '[{"phrase":"your fault"},{"phrase":"at fault"},{"phrase":"find fault with"}]', NULL, '/fɔːlt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fau/fault/fault__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 15, 'exhibit', 'trưng bày, triển lãm; thể hiện', 'verb', '[{"en":"Her paintings are being exhibited at a gallery downtown.","vi":"Các bức tranh của cô ấy đang được trưng bày tại một phòng tranh ở trung tâm thành phố."},{"en":"The museum will exhibit old photos of the city next month.","vi":"Tháng tới, bảo tàng sẽ trưng bày những bức ảnh cũ về thành phố."},{"en":"The young player exhibited great confidence throughout the match.","vi":"Cầu thủ trẻ đã thể hiện sự tự tin tuyệt vời trong suốt trận đấu."}]', '[{"phrase":"exhibit work"},{"phrase":"exhibit paintings"},{"phrase":"exhibit signs of"}]', NULL, '/ɪɡˈzɪbɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exh/exhib/exhibit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 16, 'minor', 'nhỏ, không quan trọng; nhẹ (không nghiêm trọng)', 'adjective', '[{"en":"We made a few minor changes to the plan.","vi":"Chúng tôi đã thực hiện vài thay đổi nhỏ trong kế hoạch."},{"en":"Luckily, she only had minor injuries after falling off her bike.","vi":"May mắn là cô ấy chỉ bị thương nhẹ sau khi ngã xe đạp."},{"en":"Don''t worry about it; it''s only a minor problem.","vi":"Đừng lo, đó chỉ là một vấn đề nhỏ thôi."}]', '[{"phrase":"minor changes"},{"phrase":"minor injuries"},{"phrase":"minor problem"},{"phrase":"minor role"}]', NULL, '/ˈmaɪnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minor/minor__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 17, 'hunt', 'săn, săn bắt; lùng tìm', 'verb', '[{"en":"Owls usually hunt for mice and other small animals at night.","vi":"Cú thường săn chuột và các loài vật nhỏ khác vào ban đêm."},{"en":"I hunted everywhere for my keys but couldn''t find them.","vi":"Tôi đã lục tìm chìa khóa khắp nơi nhưng không thấy."},{"en":"They are hunting for a cheap apartment near the university.","vi":"Họ đang lùng tìm một căn hộ giá rẻ gần trường đại học."}]', '[{"phrase":"hunt for"},{"phrase":"go hunting"},{"phrase":"hunt down"}]', NULL, '/hʌnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hun/hunt_/hunt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 18, 'storm', 'cơn bão; giông bão', 'noun', '[{"en":"The storm knocked down several trees on our street.","vi":"Cơn bão đã quật đổ nhiều cây trên phố chúng tôi."},{"en":"All flights were canceled because of the storm.","vi":"Tất cả các chuyến bay đều bị hủy vì bão."},{"en":"It looks like a storm is coming, so let''s go inside.","vi":"Có vẻ sắp có bão, chúng ta vào trong thôi."}]', '[{"phrase":"severe storm"},{"phrase":"tropical storm"},{"phrase":"a storm is coming"}]', NULL, '/stɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/storm/storm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-17', 19, 'thick', 'dày; đặc', 'adjective', '[{"en":"She wore a thick sweater because it was cold outside.","vi":"Cô ấy mặc một chiếc áo len dày vì ngoài trời lạnh."},{"en":"Stir the soup until it becomes thick and smooth.","vi":"Khuấy súp cho đến khi súp sánh đặc và mịn."},{"en":"It was hard to see the road through the thick fog.","vi":"Rất khó nhìn thấy đường qua lớp sương mù dày đặc."}]', '[{"phrase":"thick fog"},{"phrase":"thick hair"},{"phrase":"thick layer"},{"phrase":"thick smoke"}]', NULL, '/θɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/thick/thick__us_1.mp3', NULL, NULL);
